  from jsonb_array_elements('[{"n":1,"t":"single_choice","p":"An arithmetic sequence begins 7, 12, 17, 22, … What is the 20th term?","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An arithmetic sequence begins 7, 12, 17, 22, … What is the 20th term?"}]}]},"e":"The common difference is 5 and u_n = 7 + 5(n − 1), so u_20 = 7 + 5(19) = 102. Adding 5 twenty times (107) counts one step too many.","m":2,"df":"medium","tp":"arithmetic sequences","st":"nth term of an arithmetic sequence","cfg":{"source":"myp-mock-myp5-mock","question_number":1,"paper_section":"A","myp_criterion":"A","strand":"","next_time_hint":"u_n = u_1 + (n − 1)d: the first term is already there, so there are only n − 1 steps.","assessment_style":"myp_mock","mock_exam_key":"myp5-mock","option_labels":["102","107","100","97"],"option_key":[1],"hints":[]},"marking":"","h1":"u_n = u_1 + (n − 1)d: the first term is already there, so there are only n − 1 steps.","h2":null},{"n":2,"t":"single_choice","p":"For the sequence 4, 9, 14, 19, … what is the sum of the first 15 terms?","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"For the sequence 4, 9, 14, 19, … what is the sum of the first 15 terms?"}]}]},"e":"d = 5, so the 15th term is 4 + 14(5) = 74. Then S_15 = 15/2 × (4 + 74) = 7.5 × 78 = 585.","m":3,"df":"hard","tp":"arithmetic series","st":"sum of an arithmetic series","cfg":{"source":"myp-mock-myp5-mock","question_number":2,"paper_section":"A","myp_criterion":"A","strand":"","next_time_hint":"S_n = n/2 (u_1 + u_n). Find the last term first; forgetting the final term is the usual error.","assessment_style":"myp_mock","mock_exam_key":"myp5-mock","option_labels":["585","555","600","1 170"],"option_key":[1],"hints":[]},"marking":"","h1":"S_n = n/2 (u_1 + u_n). Find the last term first; forgetting the final term is the usual error.","h2":null},{"n":3,"t":"single_choice","p":"A geometric sequence is 3, 6, 12, 24, … What is its 8th term?","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A geometric sequence is 3, 6, 12, 24, … What is its 8th term?"}]}]},"e":"r = 2, so u_8 = 3 × 2^7 = 3 × 128 = 384. Using 2^8 would add one extra doubling.","m":3,"df":"hard","tp":"geometric sequences","st":"nth term of a geometric sequence","cfg":{"source":"myp-mock-myp5-mock","question_number":3,"paper_section":"A","myp_criterion":"A","strand":"","next_time_hint":"u_n = u_1 r^(n−1). Check the index by counting: the 2nd term uses r^1.","assessment_style":"myp_mock","mock_exam_key":"myp5-mock","option_labels":["384","768","192","48"],"option_key":[1],"hints":[]},"marking":"","h1":"u_n = u_1 r^(n−1). Check the index by counting: the 2nd term uses r^1.","h2":null},{"n":4,"t":"single_choice","p":"What is the common ratio of the geometric sequence 80, 40, 20, 10, …?","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the common ratio of the geometric sequence 80, 40, 20, 10, …?"}]}]},"e":"Each term is half the previous one: 40 ÷ 80 = 0.5, and 20 ÷ 40 = 0.5 confirms it. Subtracting (40) would be the arithmetic difference, not the ratio.","m":2,"df":"medium","tp":"geometric sequences","st":"identifying the common ratio","cfg":{"source":"myp-mock-myp5-mock","question_number":4,"paper_section":"A","myp_criterion":"A","strand":"","next_time_hint":"A common ratio is found by dividing a term by the one before it, not by subtracting.","assessment_style":"myp_mock","mock_exam_key":"myp5-mock","option_labels":["0.5","40, because the terms decrease by 40","2","−0.5"],"option_key":[1],"hints":[]},"marking":"","h1":"A common ratio is found by dividing a term by the one before it, not by subtracting.","h2":null},{"n":5,"t":"single_choice","p":"A sequence is defined by u_1 = 4 and u_{n+1} = 3u_n − 2. What is u_3?","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A sequence is defined by u_1 = 4 and u_{n+1} = 3u_n − 2. What is u_3?"}]}]},"e":"u_2 = 3(4) − 2 = 10, then u_3 = 3(10) − 2 = 28. Applying the rule twice to u_1 (giving u_2 twice) is the most common slip.","m":3,"df":"hard","tp":"recurrence relations","st":"iterating a recurrence relation","cfg":{"source":"myp-mock-myp5-mock","question_number":5,"paper_section":"A","myp_criterion":"B","strand":"","next_time_hint":"Work term by term: each application of the rule produces exactly one new term.","assessment_style":"myp_mock","mock_exam_key":"myp5-mock","option_labels":["28","10","82","34"],"option_key":[1],"hints":[]},"marking":"","h1":"Work term by term: each application of the rule produces exactly one new term.","h2":null},{"n":6,"t":"single_choice","p":"What is the value of Σ (from k = 1 to 5) of (2k + 1)?","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the value of Σ (from k = 1 to 5) of (2k + 1)?"}]}]},"e":"The terms are 3, 5, 7, 9, 11, which total 35. Substituting only the upper limit (2(5) + 1 = 11) gives a single term, not the sum.","m":3,"df":"hard","tp":"sigma notation","st":"evaluating sigma notation","cfg":{"source":"myp-mock-myp5-mock","question_number":6,"paper_section":"A","myp_criterion":"B","strand":"","next_time_hint":"Sigma means ''add the terms'': list them or use the arithmetic-sum formula.","assessment_style":"myp_mock","mock_exam_key":"myp5-mock","option_labels":["35","11","30","36"],"option_key":[1],"hints":[]},"marking":"","h1":"Sigma means ''add the terms'': list them or use the arithmetic-sum formula.","h2":null},{"n":7,"t":"single_choice","p":"What is the sum to infinity of 12 + 6 + 3 + 1.5 + …?","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the sum to infinity of 12 + 6 + 3 + 1.5 + …?"}]}]},"e":"r = 0.5 and |r| < 1, so S∞ = a/(1 − r) = 12/0.5 = 24. The sum is finite even though infinitely many terms are added.","m":3,"df":"hard","tp":"limits of series","st":"sum to infinity","cfg":{"source":"myp-mock-myp5-mock","question_number":7,"paper_section":"A","myp_criterion":"B","strand":"","next_time_hint":"S∞ = a/(1 − r) only when |r| < 1; check that condition before using the formula.","assessment_style":"myp_mock","mock_exam_key":"myp5-mock","option_labels":["24","22.5","It does not exist because the series is infinite","48"],"option_key":[1],"hints":[]},"marking":"","h1":"S∞ = a/(1 − r) only when |r| < 1; check that condition before using the formula.","h2":null},{"n":8,"t":"single_choice","p":"Which infinite geometric series converges to a finite sum?","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Which infinite geometric series converges to a finite sum?"}]}]},"e":"A geometric series converges exactly when |r| < 1. Of the four options only the one with r = 1/3 satisfies that; r = 2, r = 1.5 and r = 1 all diverge.","m":3,"df":"hard","tp":"limits of series","st":"convergence condition","cfg":{"source":"myp-mock-myp5-mock","question_number":8,"paper_section":"A","myp_criterion":"B","strand":"","next_time_hint":"Convergence needs |r| < 1. Test the ratio of consecutive terms before summing infinitely.","assessment_style":"myp_mock","mock_exam_key":"myp5-mock","option_labels":["5 + 5/3 + 5/9 + 5/27 + …","1 + 2 + 4 + 8 + …","4 + 6 + 9 + 13.5 + …","7 + 7 + 7 + 7 + …"],"option_key":[1],"hints":[]},"marking":"","h1":"Convergence needs |r| < 1. Test the ratio of consecutive terms before summing infinitely.","h2":null},{"n":9,"t":"single_choice","p":"$2 000 is invested at 5% per year compound interest. What is its value after 3 years?","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"$2 000 is invested at 5% per year compound interest. What is its value after 3 years?"}]}]},"e":"2000 × 1.05³ = 2000 × 1.157625 = $2 315.25. Adding 3 × 5% = 15% of $2 000 gives $2 300, which ignores that interest is earned on previous interest.","m":3,"df":"hard","tp":"compound interest","st":"compound interest","cfg":{"source":"myp-mock-myp5-mock","question_number":9,"paper_section":"A","myp_criterion":"C","strand":"","next_time_hint":"Compound growth multiplies repeatedly: A = P(1 + r)^n. Simple interest adds only P × r × n.","assessment_style":"myp_mock","mock_exam_key":"myp5-mock","option_labels":["$2 315.25","$2 300.00","$2 315.00","$3 000.00"],"option_key":[1],"hints":[]},"marking":"","h1":"Compound growth multiplies repeatedly: A = P(1 + r)^n. Simple interest adds only P × r × n.","h2":null},{"n":10,"t":"single_choice","p":"A machine costing $8 000 depreciates by 12% of its value each year. What is its value after 2 years?","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A machine costing "},{"type":"text","text":"$8 000 depreciates by 12% of its value each year. What is its value after 2 years?"}]}]},"e":"8000 × 0.88² = 8000 × 0.7744 = $6 195.20. Subtracting 24% of $8 000 ($6 080) is wrong because the second year''s 12% is taken from a smaller value.","m":3,"df":"hard","tp":"depreciation","st":"depreciation","cfg":{"source":"myp-mock-myp5-mock","question_number":10,"paper_section":"A","myp_criterion":"C","strand":"","next_time_hint":"Depreciation is repeated multiplication by (1 − rate), never repeated subtraction of the same amount.","assessment_style":"myp_mock","mock_exam_key":"myp5-mock","option_labels":["$6 195.20","$6 080.00","$7 040.00","$6 272.00"],"option_key":[1],"hints":[]},"marking":"","h1":"Depreciation is repeated multiplication by (1 − rate), never repeated subtraction of the same amount.","h2":null},{"n":11,"t":"single_choice","p":"Solve the exponential equation 3^x = 81 and state the value of x.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Solve the exponential equation 3^x = 81 and state the value of x."}]}]},"e":"81 = 3^4, so x = 4. Dividing 81 by 3 gives 27, which is the value of 3^x for x = 3, not the exponent itself.","m":2,"df":"medium","tp":"exponential equations","st":"solving by matching bases","cfg":{"source":"myp-mock-myp5-mock","question_number":11,"paper_section":"A","myp_criterion":"A","strand":"","next_time_hint":"Write both sides as powers of the same base, then equate the exponents.","assessment_style":"myp_mock","mock_exam_key":"myp5-mock","option_labels":["x = 4","x = 27","x = 3","x = 40.5"],"option_key":[1],"hints":[]},"marking":"","h1":"Write both sides as powers of the same base, then equate the exponents.","h2":null},{"n":12,"t":"single_choice","p":"Without a calculator, state the value of log base 2 of 32.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Without a calculator, state the value of log base 2 of 32."}]}]},"e":"log₂ 32 asks ''2 raised to what power gives 32?'' Since 32 = 2^5, the answer is 5.","m":2,"df":"medium","tp":"logarithms","st":"evaluating a logarithm","cfg":{"source":"myp-mock-myp5-mock","question_number":12,"paper_section":"A","myp_criterion":"A","strand":"","next_time_hint":"A logarithm is an exponent: log_b x = y means b^y = x.","assessment_style":"myp_mock","mock_exam_key":"myp5-mock","option_labels":["5","16","2.5","6"],"option_key":[1],"hints":[]},"marking":"","h1":"A logarithm is an exponent: log_b x = y means b^y = x.","h2":null},{"n":13,"t":"single_choice","p":"By writing both sides as powers of 2, solve 4^x = 64 and state the value of x.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"By writing both sides as powers of 2, solve 4^x = 64 and state the value of x."}]}]},"e":"4 = 2² and 64 = 2^6, so 2^(2x) = 2^6, giving 2x = 6 and x = 3. Dividing 64 by 4 (giving 16) is the value of 4², not the solution.","m":3,"df":"hard","tp":"exponential equations","st":"solving by matching bases","cfg":{"source":"myp-mock-myp5-mock","question_number":13,"paper_section":"A","myp_criterion":"B","strand":"","next_time_hint":"Convert both sides to the same base: 4^x = (2²)^x = 2^(2x).","assessment_style":"myp_mock","mock_exam_key":"myp5-mock","option_labels":["x = 3","x = 16","x = 1.5","x = 2"],"option_key":[1],"hints":[]},"marking":"","h1":"Convert both sides to the same base: 4^x = (2²)^x = 2^(2x).","h2":null},{"n":14,"t":"single_choice","p":"By factorising, state the solutions of the quadratic equation x² − 5x + 6 = 0.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"By factorising, state the solutions of the quadratic equation x² − 5x + 6 = 0."}]}]},"e":"Factorising gives (x − 2)(x − 3) = 0, so x = 2 or x = 3. The pair −2 and −3 multiplies to +6 but sums to −5 only if both signs are negative — which they are not here.","m":2,"df":"medium","tp":"quadratic functions","st":"solving a quadratic by factorising","cfg":{"source":"myp-mock-myp5-mock","question_number":14,"paper_section":"A","myp_criterion":"A","strand":"","next_time_hint":"For x² + bx + c find two numbers that multiply to c and add to b.","assessment_style":"myp_mock","mock_exam_key":"myp5-mock","option_labels":["x = 2 and x = 3","x = −2 and x = −3","x = 1 and x = 6","x = 5 and x = 6"],"option_key":[1],"hints":[]},"marking":"","h1":"For x² + bx + c find two numbers that multiply to c and add to b.","h2":null},{"n":15,"t":"single_choice","p":"The curve y = 2(x + 1)² + 7 is a parabola. What are the coordinates of its turning point?","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The curve y = 2(x + 1)² + 7 is a parabola. What are the coordinates of its turning point?"}]}]},"e":"In completed-square form y = a(x − h)² + k the turning point is (h, k). Here h = −1 (because x + 1 = x − (−1)) and k = 7, so the minimum is at (−1, 7).","m":3,"df":"hard","tp":"quadratic functions","st":"turning point from completed square","cfg":{"source":"myp-mock-myp5-mock","question_number":15,"paper_section":"A","myp_criterion":"B","strand":"","next_time_hint":"y = a(x − h)² + k has its turning point at (h, k); watch the sign inside the bracket.","assessment_style":"myp_mock","mock_exam_key":"myp5-mock","option_labels":["(−1, 7)","(1, 7)","(−1, −7)","(2, 7)"],"option_key":[1],"hints":[]},"marking":"","h1":"y = a(x − h)² + k has its turning point at (h, k); watch the sign inside the bracket.","h2":null},{"n":16,"t":"single_choice","p":"By evaluating the discriminant of the equation x² + 4x + 9 = 0, what can you conclude about its roots?","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"By evaluating the discriminant of the equation x² + 4x + 9 = 0, what can you conclude about its roots?"}]}]},"e":"b² − 4ac = 16 − 36 = −20. A negative discriminant means the equation has no real roots, so the curve does not meet the x-axis.","m":3,"df":"hard","tp":"quadratic functions","st":"the discriminant","cfg":{"source":"myp-mock-myp5-mock","question_number":16,"paper_section":"A","myp_criterion":"B","strand":"","next_time_hint":"Δ = b² − 4ac: negative means no real roots, zero means a repeated root, positive means two roots.","assessment_style":"myp_mock","mock_exam_key":"myp5-mock","option_labels":["It is negative, so there are no real roots","It is negative, so there are two equal real roots","It is positive, so there are two distinct real roots","It is zero, so the curve touches the x-axis"],"option_key":[1],"hints":[]},"marking":"","h1":"Δ = b² − 4ac: negative means no real roots, zero means a repeated root, positive means two roots.","h2":null},{"n":17,"t":"single_choice","p":"Simplify (2^5 × 2^−3) ÷ 2^4 and state the value of the result.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Simplify (2^5 × 2^−3) ÷ 2^4 and state the value of the result."}]}]},"e":"2^5 × 2^−3 = 2^2, and 2^2 ÷ 2^4 = 2^−2 = 1/4. Adding all three exponents (giving 2^6) treats a division as a multiplication.","m":3,"df":"hard","tp":"indices","st":"laws of indices","cfg":{"source":"myp-mock-myp5-mock","question_number":17,"paper_section":"A","myp_criterion":"B","strand":"","next_time_hint":"Multiplying adds exponents, dividing subtracts them, and a negative exponent means a reciprocal.","assessment_style":"myp_mock","mock_exam_key":"myp5-mock","option_labels":["1/4","4","64","1/2"],"option_key":[1],"hints":[]},"marking":"","h1":"Multiplying adds exponents, dividing subtracts them, and a negative exponent means a reciprocal.","h2":null},{"n":18,"t":"single_choice","p":"Solve 5^(2x − 1) = 125 and state the value of x.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Solve 5^(2x − 1) = 125 and state the value of x."}]}]},"e":"125 = 5³, so 2x − 1 = 3 and x = 2. Setting 2x − 1 = 125 divides instead of matching exponents.","m":3,"df":"hard","tp":"exponential equations","st":"solving by matching bases","cfg":{"source":"myp-mock-myp5-mock","question_number":18,"paper_section":"A","myp_criterion":"B","strand":"","next_time_hint":"Rewrite 125 as a power of 5 first, then equate the exponents and solve the linear equation.","assessment_style":"myp_mock","mock_exam_key":"myp5-mock","option_labels":["x = 2","x = 63","x = 1","x = 2.5"],"option_key":[1],"hints":[]},"marking":"","h1":"Rewrite 125 as a power of 5 first, then equate the exponents and solve the linear equation.","h2":null},{"n":19,"t":"single_choice","p":"A geometric sequence has u_1 = 5 and r = −2. What is u_6?","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A geometric sequence has u_1 = 5 and r = −2. What is u_6?"}]}]},"e":"u_6 = 5 × (−2)^5 = 5 × (−32) = −160. The sign alternates, so an even-indexed term is now negative: u_6 uses an odd power of −2.","m":3,"df":"hard","tp":"geometric sequences","st":"negative common ratio","cfg":{"source":"myp-mock-myp5-mock","question_number":19,"paper_section":"A","myp_criterion":"B","strand":"","next_time_hint":"A negative ratio alternates signs; (−2)^5 is negative because the power is odd.","assessment_style":"myp_mock","mock_exam_key":"myp5-mock","option_labels":["−160","160","−320","−62"],"option_key":[1],"hints":[]},"marking":"","h1":"A negative ratio alternates signs; (−2)^5 is negative because the power is odd.","h2":null},{"n":20,"t":"single_choice","p":"An infinite geometric series has first term a and common ratio r. Which condition guarantees a finite sum?","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An infinite geometric series has first term a and common ratio r. Which condition guarantees a finite sum?"}]}]},"e":"The formula S∞ = a/(1 − r) requires |r| < 1, which is what makes the terms shrink towards zero fast enough for the total to settle.","m":2,"df":"medium","tp":"limits of series","st":"convergence condition","cfg":{"source":"myp-mock-myp5-mock","question_number":20,"paper_section":"A","myp_criterion":"A","strand":"","next_time_hint":"Only a ratio smaller than 1 in size makes the successive terms shrink.","assessment_style":"myp_mock","mock_exam_key":"myp5-mock","option_labels":["|r| < 1","r > 0","a < r","|r| > 1"],"option_key":[1],"hints":[]},"marking":"","h1":"Only a ratio smaller than 1 in size makes the successive terms shrink.","h2":null},{"n":21,"t":"single_choice","p":"Three numbers form an arithmetic sequence. The first term is 5 and the third term is 21. What is the middle number?","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Three numbers form an arithmetic sequence. The first term is 5 and the third term is 21. What is the middle number?"}]}]},"e":"In an arithmetic sequence the middle term is the mean of its neighbours: (5 + 21)/2 = 13, giving d = 8. Halving the difference (8) alone gives the step, not the middle term.","m":3,"df":"hard","tp":"arithmetic sequences","st":"arithmetic mean","cfg":{"source":"myp-mock-myp5-mock","question_number":21,"paper_section":"A","myp_criterion":"B","strand":"","next_time_hint":"With equal steps, the middle term is exactly halfway between the outer two.","assessment_style":"myp_mock","mock_exam_key":"myp5-mock","option_labels":["13","8","16","26"],"option_key":[1],"hints":[]},"marking":"","h1":"With equal steps, the middle term is exactly halfway between the outer two.","h2":null},{"n":22,"t":"single_choice","p":"Two membership models both start at $100. Model L adds $3 for every visit. Model E multiplies the total by 1.5 for every block of visits completed, so it grows by a constant factor. Which statement is justified?","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Two membership models both start at "},{"type":"text","text":"$100. Model L adds $"},{"type":"text","text":"3 for every visit. Model E multiplies the total by 1.5 for every block of visits completed, so it grows by a constant factor. Which statement is justified?"}]}]},"e":"A linear model (100 + 3n) grows by a constant amount each visit, while a doubling model grows by a constant factor. The exponential model starts lower but inevitably overtakes the linear one and then grows far faster, so ''linear is always cheaper'' is false.","m":3,"df":"hard","tp":"modelling","st":"comparing linear and exponential growth","cfg":{"source":"myp-mock-myp5-mock","question_number":22,"paper_section":"A","myp_criterion":"D","strand":"","next_time_hint":"Linear growth adds a constant; exponential growth multiplies by a constant, so it eventually dominates.","assessment_style":"myp_mock","mock_exam_key":"myp5-mock","option_labels":["The doubling model eventually overtakes the linear one and then grows far faster","The linear model is always cheaper because it starts lower","Both models grow at the same rate because both start at 100","The doubling model exceeds the linear one after every single visit"],"option_key":[1],"hints":[]},"marking":"","h1":"Linear growth adds a constant; exponential growth multiplies by a constant, so it eventually dominates.","h2":null},{"n":23,"t":"assess_parts","p":"A theatre has 24 rows of seats. The first row has 18 seats and each row has 2 more seats than the row in front of it.\n\n(a) State the number of seats in the 10th row.\n(b) Calculate the total number of seats in the theatre.\n(c) A renovation adds one extra seat to every row. Explain how the total changes.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A theatre has 24 rows of seats. The first row has 18 seats and each row has 2 more seats than the row in front of it."}]},{"type":"paragraph","content":[{"type":"text","text":"(a) State the number of seats in the 10th row.\n(b) Calculate the total number of seats in the theatre.\n(c) A renovation adds one extra seat to every row. Explain how the total changes."}]}]},"e":"u_10 = 36, u_24 = 64, so S_24 = 12 × 82 = 984 seats. Adding one seat per row adds 24 seats.","m":8,"df":"hard","tp":"arithmetic sequences","st":"arithmetic sequences","cfg":{"source":"myp-mock-myp5-mock","question_number":23,"paper_section":"B","myp_criterion":"C","strand":"C(i)","next_time_hint":"For an arithmetic series find the first and last terms, then apply S_n = n/2 (u_1 + u_n).","assessment_style":"myp_mock","mock_exam_key":"myp5-mock","parts":[{"id":"a","label":"(a)","prompt":"State the number of seats in the 10th row.","kind":"numeric","points":1,"hints":["The first row has 18 seats and each row adds 2.","u_n = 18 + 2(n − 1), so use n = 10."],"strand":"C(i)","answer":36,"tolerance":0},{"id":"b","label":"(b)","prompt":"State the number of seats in the last (24th) row.","kind":"numeric","points":2,"hints":["Use n = 24 in the nth-term formula.","18 + 2(23)."],"strand":"C(ii)","answer":64,"tolerance":0},{"id":"c","label":"(c)","prompt":"Calculate the total number of seats in the theatre.","kind":"numeric","points":3,"hints":["S_n = n/2 × (first + last).","24/2 × (18 + 64)."],"strand":"C(iii)","answer":984,"tolerance":0,"unit":"seats"},{"id":"d","label":"(d)","prompt":"Explain how the total changes when one seat is added to every row.","kind":"text","points":2,"hints":["How many rows are there?","Each row gains exactly one seat."],"strand":"C(iv)","accepted":["the total rises by 24 seats, one for each of the 24 rows, giving 1008"],"keywords":[["total"],["rises"],["seats"],["rows"],["giving"]],"minKeywordGroups":3}],"marking":"(a) 1 mark. (b) 2 marks: 1 for substituting n = 24, 1 for 64. (c) 3 marks: 1 for the formula, 1 for 82, 1 for 984. (d) 2 marks: 1 for 24 seats, 1 for 1 008.","marking_criteria":"(a) 1 mark. (b) 2 marks: 1 for substituting n = 24, 1 for 64. (c) 3 marks: 1 for the formula, 1 for 82, 1 for 984. (d) 2 marks: 1 for 24 seats, 1 for 1 008.","response_tools":["rich_text","math","table"],"response_requirement":"text","response_guidance":"Write the nth-term formula explicitly in (a); the same formula drives (b) and (c)."},"marking":"(a) 1 mark. (b) 2 marks: 1 for substituting n = 24, 1 for 64. (c) 3 marks: 1 for the formula, 1 for 82, 1 for 984. (d) 2 marks: 1 for 24 seats, 1 for 1 008.","h1":"For an arithmetic series find the first and last terms, then apply S_n = n/2 (u_1 + u_n).","h2":"The first row has 18 seats and each row adds 2."},{"n":24,"t":"assess_parts","p":"A culture of bacteria doubles every 3 hours. It starts with 500 bacteria.\n\n(a) State the number of bacteria after 12 hours.\n(b) Explain why the number after t hours is not a linear function of t.\n(c) Calculate the number of complete 3-hour periods needed for the population to exceed 50 000.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A culture of bacteria doubles every 3 hours. It starts with 500 bacteria."}]},{"type":"paragraph","content":[{"type":"text","text":"(a) State the number of bacteria after 12 hours.\n(b) Explain why the number after t hours is not a linear function of t.\n(c) Calculate the number of complete 3-hour periods needed for the population to exceed 50 000."}]}]},"e":"Four periods give 500 × 16 = 8 000 bacteria. The growth is 500 × 2^(t/3), a geometric model. 2^k > 100 first holds at k = 7 (128), so 7 periods are needed.","m":8,"df":"hard","tp":"geometric sequences","st":"geometric sequences","cfg":{"source":"myp-mock-myp5-mock","question_number":24,"paper_section":"B","myp_criterion":"C","strand":"C(i)","next_time_hint":"Doubling is multiplication: count periods, then use a power. Compare with linear growth explicitly.","assessment_style":"myp_mock","mock_exam_key":"myp5-mock","parts":[{"id":"a","label":"(a)","prompt":"State the number of doubling periods in 12 hours.","kind":"numeric","points":1,"hints":["The population doubles every 3 hours.","Divide 12 by 3."],"strand":"C(i)","answer":4,"tolerance":0},{"id":"b","label":"(b)","prompt":"Calculate the number of bacteria after 12 hours.","kind":"numeric","points":2,"hints":["Multiply the starting 500 by 2 once for each period.","500 × 2^4."],"strand":"C(ii)","answer":8000,"tolerance":0,"unit":"bacteria"},{"id":"c","label":"(c)","prompt":"Explain why the population is not a linear function of time.","kind":"text","points":2,"hints":["Compare what happens in successive 3-hour periods.","Is a constant amount added each period, or a constant factor?"],"strand":"C(iii)","accepted":["each period multiplies the population by 2 rather than adding a fixed number, so the growth is geometric (exponential), not linear"],"keywords":[["period"],["multiplies"],["population"],["rather"],["adding"],["fixed"]],"minKeywordGroups":4},{"id":"d","label":"(d)","prompt":"Calculate the number of complete periods needed to exceed 50 000 bacteria.","kind":"numeric","points":3,"hints":["You need 500 × 2^k > 50 000, so 2^k > 100.","2^6 = 64 and 2^7 = 128, so take the first k that works."],"strand":"C(iv)","answer":7,"tolerance":0,"unit":"periods"}],"marking":"(a) 1 mark. (b) 2 marks: 1 for 2^4, 1 for 8 000. (c) 2 marks: 1 for ''multiply by 2'', 1 for the linear contrast. (d) 3 marks: 1 for the inequality 2^k > 100, 1 for testing powers, 1 for 7.","marking_criteria":"(a) 1 mark. (b) 2 marks: 1 for 2^4, 1 for 8 000. (c) 2 marks: 1 for ''multiply by 2'', 1 for the linear contrast. (d) 3 marks: 1 for the inequality 2^k > 100, 1 for testing powers, 1 for 7.","response_tools":["graph","rich_text","math"],"response_requirement":"graph","response_guidance":"Plot the population against the period number in the workspace: the curve (not a straight line) is the evidence for (c)."},"marking":"(a) 1 mark. (b) 2 marks: 1 for 2^4, 1 for 8 000. (c) 2 marks: 1 for ''multiply by 2'', 1 for the linear contrast. (d) 3 marks: 1 for the inequality 2^k > 100, 1 for testing powers, 1 for 7.","h1":"Doubling is multiplication: count periods, then use a power. Compare with linear growth explicitly.","h2":"The population doubles every 3 hours."},{"n":25,"t":"assess_parts","p":"Amara invests $5 000 at 4% per year compound interest. Her friend Ben invests $5 000 at 4% per year simple interest.\n\n(a) Calculate the value of Amara''s investment after 5 years.\n(b) Calculate the value of Ben''s investment after 5 years.\n(c) Explain why the difference grows each year.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Amara invests "},{"type":"text","text":"$5 000 at 4% per year compound interest. Her friend Ben invests $"},{"type":"text","text":"5 000 at 4% per year simple interest."}]},{"type":"paragraph","content":[{"type":"text","text":"(a) Calculate the value of Amara''s investment after 5 years.\n(b) Calculate the value of Ben''s investment after 5 years.\n(c) Explain why the difference grows each year."}]}]},"e":"Amara: 5000(1.04)^5 = $6 083.26. Ben: 5000 + 5(200) = $6 000. The $83.26 gap exists because Amara''s interest compounds, so each year''s interest is calculated on a larger balance.","m":8,"df":"hard","tp":"compound interest","st":"compound interest","cfg":{"source":"myp-mock-myp5-mock","question_number":25,"paper_section":"B","myp_criterion":"C","strand":"C(i)","next_time_hint":"Compound interest is geometric; simple interest is arithmetic. State the base each year''s interest is calculated on.","assessment_style":"myp_mock","mock_exam_key":"myp5-mock","parts":[{"id":"a","label":"(a)","prompt":"Calculate the value of Amara''s investment after 5 years, to the nearest cent.","kind":"numeric","points":3,"hints":["Use A = P(1 + r)^n with r = 0.04 and n = 5.","5000 × 1.04^5."],"strand":"C(i)","answer":6083.26,"tolerance":0.05,"unit":"$"},{"id":"b","label":"(b)","prompt":"Calculate the value of Ben''s investment after 5 years.","kind":"numeric","points":2,"hints":["Simple interest adds 4% of $5 000 each year.","5000 + 5 × 200."],"strand":"C(ii)","answer":6000,"tolerance":0.01,"unit":"$"},{"id":"c","label":"(c)","prompt":"Explain why the gap between the two investments widens each year.","kind":"text","points":3,"hints":["What is each person''s interest calculated on?","Does Ben''s interest ever earn interest?"],"strand":"C(iii)","accepted":["amara earns interest on the interest she has already received, so her balance grows by an increasing amount, while ben always earns 4% of the original $5000"],"keywords":[["amara"],["earns"],["interest"],["already"],["received"],["balance"]],"minKeywordGroups":4}],"marking":"(a) 3 marks: 1 for the formula, 1 for 1.04^5, 1 for $6 083.26. (b) 2 marks: 1 for 5 × 200, 1 for $6 000. (c) 3 marks: 1 for ''interest on interest'', 1 for the constant simple base, 1 for the widening gap.","marking_criteria":"(a) 3 marks: 1 for the formula, 1 for 1.04^5, 1 for $6 083.26. (b) 2 marks: 1 for 5 × 200, 1 for $6 000. (c) 3 marks: 1 for ''interest on interest'', 1 for the constant simple base, 1 for the widening gap.","response_tools":["rich_text","math"],"response_requirement":"text","response_guidance":"Show P(1 + r)^n with the numbers substituted; the exponent is the point being assessed."},"marking":"(a) 3 marks: 1 for the formula, 1 for 1.04^5, 1 for $6 083.26. (b) 2 marks: 1 for 5 × 200, 1 for $6 000. (c) 3 marks: 1 for ''interest on interest'', 1 for the constant simple base, 1 for the widening gap.","h1":"Compound interest is geometric; simple interest is arithmetic. State the base each year''s interest is calculated on.","h2":"Use A = P(1 + r)^n with r = 0.04 and n = 5."},{"n":26,"t":"assess_parts","p":"A ball is dropped from 2 m. After each bounce it rises to 60% of its previous height.\n\n(a) State the height after the first bounce.\n(b) Calculate the height after the third bounce.\n(c) Calculate the total vertical distance travelled before the ball comes to rest.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A ball is dropped from 2 m. After each bounce it rises to 60% of its previous height."}]},{"type":"paragraph","content":[{"type":"text","text":"(a) State the height after the first bounce.\n(b) Calculate the height after the third bounce.\n(c) Calculate the total vertical distance travelled before the ball comes to rest."}]}]},"e":"Bounce heights 1.2, 0.72, 0.432, … have sum 1.2/0.4 = 3 m. The ball travels that sum up and down, so 2 × 3 = 6 m of bounces, plus the initial 2 m fall: 8 m in total.","m":10,"df":"hard","tp":"limits of series","st":"limits of series","cfg":{"source":"myp-mock-myp5-mock","question_number":26,"paper_section":"B","myp_criterion":"D","strand":"D(i)","next_time_hint":"In a bouncing-ball problem, list the bounce heights as a geometric sequence and remember each bounce is travelled twice.","assessment_style":"myp_mock","mock_exam_key":"myp5-mock","parts":[{"id":"a","label":"(a)","prompt":"State the height after the first bounce, in metres.","kind":"numeric","points":1,"hints":["60% of the 2 m drop.","2 × 0.6."],"strand":"D(i)","answer":1.2,"tolerance":0.01,"unit":"m"},{"id":"b","label":"(b)","prompt":"Calculate the height after the third bounce, in metres.","kind":"numeric","points":2,"hints":["The heights form a geometric sequence with r = 0.6.","2 × 0.6^3."],"strand":"D(ii)","answer":0.432,"tolerance":0.002,"unit":"m"},{"id":"c","label":"(c)","prompt":"Explain why the bounce distances are multiplied by 2 in the total distance.","kind":"text","points":3,"hints":["Does the ball only go up, or up and then down?","Each bounce contributes a rise and an equal fall."],"strand":"D(iii)","accepted":["each bounce is travelled going up and again coming down, so the bounce sum is counted twice, plus the original 2 m drop"],"keywords":[["bounce"],["travelled"],["going"],["again"],["coming"],["down"]],"minKeywordGroups":4},{"id":"d","label":"(d)","prompt":"Calculate the total vertical distance before the ball comes to rest, in metres.","kind":"numeric","points":4,"hints":["Sum the bounce heights with S∞ = a/(1 − r).","Add the original 2 m fall and double the bounce sum."],"strand":"D(iv)","answer":8,"tolerance":0.05,"unit":"m"}],"marking":"(a) 1 mark. (b) 2 marks: 1 for the ratio, 1 for 0.432. (c) 3 marks: 1 for ''up and down'', 1 for the doubling, 1 for including the first drop. (d) 4 marks: 1 for S∞, 1 for 3 m, 1 for 6 m, 1 for 8 m.","marking_criteria":"(a) 1 mark. (b) 2 marks: 1 for the ratio, 1 for 0.432. (c) 3 marks: 1 for ''up and down'', 1 for the doubling, 1 for including the first drop. (d) 4 marks: 1 for S∞, 1 for 3 m, 1 for 6 m, 1 for 8 m.","response_tools":["rich_text","math"],"response_requirement":"text","response_guidance":"Write the bounce heights as a sequence before summing; the doubling in (c) is where most marks are lost."},"marking":"(a) 1 mark. (b) 2 marks: 1 for the ratio, 1 for 0.432. (c) 3 marks: 1 for ''up and down'', 1 for the doubling, 1 for including the first drop. (d) 4 marks: 1 for S∞, 1 for 3 m, 1 for 6 m, 1 for 8 m.","h1":"In a bouncing-ball problem, list the bounce heights as a geometric sequence and remember each bounce is travelled twice.","h2":"60% of the 2 m drop."},{"n":27,"t":"assess_parts","p":"The 2nd term of a geometric sequence is 12 and the 5th term is 96.\n\n(a) Explain how to find the common ratio from these two terms.\n(b) Calculate the common ratio.\n(c) Calculate the first term.\n(d) State the 7th term.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The 2nd term of a geometric sequence is 12 and the 5th term is 96."}]},{"type":"paragraph","content":[{"type":"text","text":"(a) Explain how to find the common ratio from these two terms.\n(b) Calculate the common ratio.\n(c) Calculate the first term.\n(d) State the 7th term."}]}]},"e":"u_5/u_2 = r³ = 8 gives r = 2, so u_1 = 12/2 = 6 and u_7 = 6 × 2^6 = 384.","m":8,"df":"hard","tp":"geometric sequences","st":"geometric sequences","cfg":{"source":"myp-mock-myp5-mock","question_number":27,"paper_section":"B","myp_criterion":"C","strand":"C(i)","next_time_hint":"Dividing two terms of a geometric sequence gives r raised to the difference in their positions.","assessment_style":"myp_mock","mock_exam_key":"myp5-mock","parts":[{"id":"a","label":"(a)","prompt":"Explain how the two terms give the common ratio.","kind":"text","points":2,"hints":["Write u_2 and u_5 in terms of u_1 and r.","How many factors of r separate the 2nd and 5th terms?"],"strand":"C(i)","accepted":["dividing u_5 by u_2 removes the first term and leaves r^3, because the terms are three positions apart"],"keywords":[["dividing"],["removes"],["first"],["term"],["leaves"],["terms"]],"minKeywordGroups":4},{"id":"b","label":"(b)","prompt":"Calculate the common ratio.","kind":"numeric","points":2,"hints":["96 ÷ 12 = 8, and that equals r³.","Take the cube root of 8."],"strand":"C(ii)","answer":2,"tolerance":0},{"id":"c","label":"(c)","prompt":"Calculate the first term.","kind":"numeric","points":2,"hints":["u_2 = u_1 × r.","12 = 2 × u_1."],"strand":"C(iii)","answer":6,"tolerance":0},{"id":"d","label":"(d)","prompt":"State the 7th term.","kind":"numeric","points":2,"hints":["The 7th term is six multiplications of r after the first term.","u_7 = 6 × 2^6."],"strand":"C(iv)","answer":384,"tolerance":0}],"marking":"(a) 2 marks: 1 for the division, 1 for ''three positions, so r cubed''. (b) 2 marks: 1 for 8, 1 for r = 2. (c) 2 marks: 1 for substituting, 1 for 6. (d) 2 marks: 1 for r^6, 1 for 384.","marking_criteria":"(a) 2 marks: 1 for the division, 1 for ''three positions, so r cubed''. (b) 2 marks: 1 for 8, 1 for r = 2. (c) 2 marks: 1 for substituting, 1 for 6. (d) 2 marks: 1 for r^6, 1 for 384.","response_tools":["rich_text","math"],"response_requirement":"text","response_guidance":"In (a) use the word ''divide'' and the difference in position (3 steps); that is the reasoning being marked."},"marking":"(a) 2 marks: 1 for the division, 1 for ''three positions, so r cubed''. (b) 2 marks: 1 for 8, 1 for r = 2. (c) 2 marks: 1 for substituting, 1 for 6. (d) 2 marks: 1 for r^6, 1 for 384.","h1":"Dividing two terms of a geometric sequence gives r raised to the difference in their positions.","h2":"Write u_2 and u_5 in terms of u_1 and r."},{"n":28,"t":"assess_parts","p":"A savings plan pays $200 in month 1, $220 in month 2, $240 in month 3, and so on, increasing by $20 each month.\n\n(a) State the amount paid in month 12.\n(b) Calculate the total saved after 12 months.\n(c) Explain how many months are needed for the total to exceed $5 000, setting up the inequality you would solve.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A savings plan pays "},{"type":"text","text":"$200 in month 1, $"},{"type":"text","text":"220 in month 2, "},{"type":"text","text":"$240 in month 3, and so on, increasing by $"},{"type":"text","text":"20 each month."}]},{"type":"paragraph","content":[{"type":"text","text":"(a) State the amount paid in month 12.\n(b) Calculate the total saved after 12 months.\n(c) Explain how many months are needed for the total to exceed "},{"type":"text","text":"$5 000, setting up the inequality you would solve."}]}]},"e":"Month 12 is 200 + 11(20) = $420 and S_12 = 6(620) = $3 720. S_14 = 7(200 + 460) = $4 620, which is still below 5000, while S_15 = 7.5(200 + 480) = $5 100 exceeds it, so 15 months are needed.","m":9,"df":"hard","tp":"sigma notation","st":"sigma notation","cfg":{"source":"myp-mock-myp5-mock","question_number":28,"paper_section":"B","myp_criterion":"D","strand":"D(i)","next_time_hint":"For ''when does the total exceed X'', compute running sums and bracket the answer between two months rather than guessing.","assessment_style":"myp_mock","mock_exam_key":"myp5-mock","parts":[{"id":"a","label":"(a)","prompt":"State the amount paid in month 12, in dollars.","kind":"numeric","points":1,"hints":["The amounts form an arithmetic sequence with d = 20.","200 + 11 × 20."],"strand":"D(i)","answer":420,"tolerance":0},{"id":"b","label":"(b)","prompt":"Calculate the total saved after 12 months, in dollars.","kind":"numeric","points":3,"hints":["S_n = n/2 × (first + last).","12/2 × (200 + 420)."],"strand":"D(ii)","answer":3720,"tolerance":0.01,"unit":"$"},{"id":"c","label":"(c)","prompt":"State the total saved after 14 months, in dollars.","kind":"numeric","points":3,"hints":["Use the formula with n = 14 and last term 200 + 13(20).","14/2 × (200 + 460)."],"strand":"D(iii)","answer":4620,"tolerance":0.01,"unit":"$"},{"id":"d","label":"(d)","prompt":"State the first month for which the total exceeds $5 000.","kind":"numeric","points":2,"hints":["Compare your 14-month total with 5000; it is still short.","Add one more month''s payment to your 14-month total and compare again."],"strand":"D(iv)","answer":15,"tolerance":0,"unit":"months"}],"marking":"(a) 1 mark. (b) 3 marks: 1 for the formula, 1 for the last term, 1 for $3 720. (c) 3 marks: 1 for n = 14, 1 for the last term 460, 1 for $4 620. (d) 2 marks: 1 for comparing, 1 for 15 months.","marking_criteria":"(a) 1 mark. (b) 3 marks: 1 for the formula, 1 for the last term, 1 for $3 720. (c) 3 marks: 1 for n = 14, 1 for the last term 460, 1 for $4 620. (d) 2 marks: 1 for comparing, 1 for 15 months.","response_tools":["rich_text","math","table"],"response_requirement":"text","response_guidance":"Build the monthly totals in the workspace table; the sequence of running totals answers (d) directly."},"marking":"(a) 1 mark. (b) 3 marks: 1 for the formula, 1 for the last term, 1 for $3 720. (c) 3 marks: 1 for n = 14, 1 for the last term 460, 1 for $4 620. (d) 2 marks: 1 for comparing, 1 for 15 months.","h1":"For ''when does the total exceed X'', compute running sums and bracket the answer between two months rather than guessing.","h2":"The amounts form an arithmetic sequence with d = 20."},{"n":29,"t":"assess_parts","p":"The number of bacteria in a dish is modelled by N = 300 × 2^t, where t is in hours.\n\n(a) State the initial number of bacteria.\n(b) Calculate the number of bacteria after 5 hours.\n(c) Using logarithms, calculate the time for the population to reach 20 000, to 2 decimal places.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The number of bacteria in a dish is modelled by N = 300 × 2^t, where t is in hours."}]},{"type":"paragraph","content":[{"type":"text","text":"(a) State the initial number of bacteria.\n(b) Calculate the number of bacteria after 5 hours.\n(c) Using logarithms, calculate the time for the population to reach 20 000, to 2 decimal places."}]}]},"e":"N(0) = 300 and N(5) = 9 600. For 20 000, 2^t = 66.67 so t = log 66.67 / log 2 ≈ 6.06 hours.","m":8,"df":"hard","tp":"exponential equations","st":"exponential equations","cfg":{"source":"myp-mock-myp5-mock","question_number":29,"paper_section":"B","myp_criterion":"C","strand":"C(i)","next_time_hint":"To solve for an exponent, isolate the power and take logarithms of both sides.","assessment_style":"myp_mock","mock_exam_key":"myp5-mock","parts":[{"id":"a","label":"(a)","prompt":"State the initial number of bacteria.","kind":"numeric","points":1,"hints":["Substitute t = 0.","2^0 = 1."],"strand":"C(i)","answer":300,"tolerance":0},{"id":"b","label":"(b)","prompt":"Calculate the number of bacteria after 5 hours.","kind":"numeric","points":2,"hints":["Substitute t = 5.","300 × 32."],"strand":"C(ii)","answer":9600,"tolerance":0,"unit":"bacteria"},{"id":"c","label":"(c)","prompt":"State the value of 20 000 ÷ 300, to 3 significant figures.","kind":"numeric","points":2,"hints":["Divide the target by the initial population.","This equals 2^t."],"strand":"C(iii)","answer":66.7,"tolerance":0.1},{"id":"d","label":"(d)","prompt":"Calculate the time to reach 20 000 bacteria, to 2 decimal places.","kind":"numeric","points":3,"hints":["Take logarithms of both sides: t = log(66.67) ÷ log(2).","Your answer should be a little more than 6 hours."],"strand":"C(iv)","answer":6.06,"tolerance":0.03,"unit":"hours"}],"marking":"(a) 1 mark. (b) 2 marks: 1 for 2^5, 1 for 9 600. (c) 2 marks: 1 for the division, 1 for 66.7. (d) 3 marks: 1 for the log equation, 1 for the evaluated logarithms, 1 for 6.06.","marking_criteria":"(a) 1 mark. (b) 2 marks: 1 for 2^5, 1 for 9 600. (c) 2 marks: 1 for the division, 1 for 66.7. (d) 3 marks: 1 for the log equation, 1 for the evaluated logarithms, 1 for 6.06.","response_tools":["rich_text","math"],"response_requirement":"text","response_guidance":"Show the logarithm step in (d); the division only sets up the equation."},"marking":"(a) 1 mark. (b) 2 marks: 1 for 2^5, 1 for 9 600. (c) 2 marks: 1 for the division, 1 for 66.7. (d) 3 marks: 1 for the log equation, 1 for the evaluated logarithms, 1 for 6.06.","h1":"To solve for an exponent, isolate the power and take logarithms of both sides.","h2":"Substitute t = 0."},{"n":30,"t":"assess_parts","p":"A ball is thrown upwards. Its height in metres after t seconds is h = 20t − 5t².\n\n(a) Calculate the height after 1 second.\n(b) Show that the ball returns to the ground at t = 4.\n(c) State the time at which the ball reaches its maximum height.\n(d) Calculate the maximum height.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A ball is thrown upwards. Its height in metres after t seconds is h = 20t − 5t²."}]},{"type":"paragraph","content":[{"type":"text","text":"(a) Calculate the height after 1 second.\n(b) Show that the ball returns to the ground at t = 4.\n(c) State the time at which the ball reaches its maximum height.\n(d) Calculate the maximum height."}]}]},"e":"h(1) = 15 m; the roots are t = 0 and t = 4; the vertex is at t = 2 giving h = 20 m. Beyond t = 4 the formula produces negative heights, so the physical model stops at the landing time.","m":9,"df":"hard","tp":"quadratic functions","st":"quadratic functions","cfg":{"source":"myp-mock-myp5-mock","question_number":30,"paper_section":"B","myp_criterion":"D","strand":"D(i)","next_time_hint":"For a quadratic model, roots give the start and end, and the vertex lies halfway between them.","assessment_style":"myp_mock","mock_exam_key":"myp5-mock","parts":[{"id":"a","label":"(a)","prompt":"Calculate the height after 1 second, in metres.","kind":"numeric","points":1,"hints":["Put t = 1 into the height equation, taking care with the squared term.","20(1) − 5(1)²."],"strand":"D(i)","answer":15,"tolerance":0,"unit":"m"},{"id":"b","label":"(b)","prompt":"State the non-zero time at which the ball returns to the ground.","kind":"numeric","points":2,"hints":["Set h = 0 and factorise.","5t(4 − t) = 0."],"strand":"D(ii)","answer":4,"tolerance":0,"unit":"s"},{"id":"c","label":"(c)","prompt":"State the time of maximum height, in seconds.","kind":"numeric","points":2,"hints":["The maximum is halfway between the two roots.","Half of 4."],"strand":"D(iii)","answer":2,"tolerance":0,"unit":"s"},{"id":"d","label":"(d)","prompt":"Calculate the maximum height, in metres.","kind":"numeric","points":2,"hints":["Substitute t = 2 into the height equation.","40 − 20."],"strand":"D(iv)","answer":20,"tolerance":0,"unit":"m"},{"id":"e","label":"(e)","prompt":"Explain why the model cannot be used for t = 5.","kind":"text","points":2,"hints":["What does the equation give at t = 5?","Can a ball be below the ground?"],"strand":"D(iv)","accepted":["at t = 5 the equation gives −25 m, a negative height, and the ball has already landed, so the model only applies until t = 4"],"keywords":[["equation"],["gives"],["negative"],["height"],["ball"],["already"]],"minKeywordGroups":4}],"marking":"(a) 1 mark. (b) 2 marks: 1 for factorising, 1 for t = 4. (c) 2 marks: 1 for the midpoint, 1 for 2 s. (d) 2 marks: 1 for substituting, 1 for 20 m. (e) 2 marks: 1 for the negative height, 1 for the valid range.","marking_criteria":"(a) 1 mark. (b) 2 marks: 1 for factorising, 1 for t = 4. (c) 2 marks: 1 for the midpoint, 1 for 2 s. (d) 2 marks: 1 for substituting, 1 for 20 m. (e) 2 marks: 1 for the negative height, 1 for the valid range.","response_tools":["graph","rich_text","math"],"response_requirement":"graph","response_guidance":"Plot h = 20t − 5t² in the workspace and read the vertex from the graph to check (c) and (d)."},"marking":"(a) 1 mark. (b) 2 marks: 1 for factorising, 1 for t = 4. (c) 2 marks: 1 for the midpoint, 1 for 2 s. (d) 2 marks: 1 for substituting, 1 for 20 m. (e) 2 marks: 1 for the negative height, 1 for the valid range.","h1":"For a quadratic model, roots give the start and end, and the vertex lies halfway between them.","h2":"Put t = 1 into the height equation, taking care with the squared term."},{"n":31,"t":"assess_parts","p":"The loudness of a sound in decibels is L = 10 log₁₀(I / I₀), where I₀ is the threshold of hearing.\n\n(a) State the loudness when I = 1 000 I₀.\n(b) State the loudness when I = 10 000 I₀.\n(c) Explain why multiplying the intensity by 10 adds exactly 10 decibels.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The loudness of a sound in decibels is L = 10 log₁₀(I / I₀), where I₀ is the threshold of hearing."}]},{"type":"paragraph","content":[{"type":"text","text":"(a) State the loudness when I = 1 000 I₀.\n(b) State the loudness when I = 10 000 I₀.\n(c) Explain why multiplying the intensity by 10 adds exactly 10 decibels."}]}]},"e":"1000 I₀ gives 30 dB and 10 000 I₀ gives 40 dB. Since log(10x) = log x + 1, each tenfold increase in intensity adds 10 dB, which is why decibels are a logarithmic scale.","m":5,"df":"hard","tp":"logarithms","st":"logarithms","cfg":{"source":"myp-mock-myp5-mock","question_number":31,"paper_section":"B","myp_criterion":"C","strand":"C(i)","next_time_hint":"A logarithmic scale turns multiplication into addition: a constant factor becomes a constant difference.","assessment_style":"myp_mock","mock_exam_key":"myp5-mock","parts":[{"id":"a","label":"(a)","prompt":"State the loudness when I = 1 000 I₀, in decibels.","kind":"numeric","points":1,"hints":["The ratio I/I₀ is 1000.","10 × log(1000) and log(1000) = 3."],"strand":"C(i)","answer":30,"tolerance":0,"unit":"dB"},{"id":"b","label":"(b)","prompt":"State the loudness when I = 10 000 I₀, in decibels.","kind":"numeric","points":1,"hints":["The intensity ratio is now 10 000.","log(10 000) = 4, so evaluate 10 × 4."],"strand":"C(i)","answer":40,"tolerance":0,"unit":"dB"},{"id":"c","label":"(c)","prompt":"Explain why a tenfold increase in intensity adds 10 dB.","kind":"text","points":3,"hints":["Use log(10x) = log x + 1.","The formula multiplies the logarithm by 10."],"strand":"C(ii)","accepted":["multiplying the intensity by ten adds 1 to the logarithm, and the formula multiplies the logarithm by 10, so the loudness rises by exactly 10 dB"],"keywords":[["multiplying"],["intensity"],["adds"],["logarithm"],["formula"],["multiplies"]],"minKeywordGroups":4}],"marking":"(a) 1 mark. (b) 1 mark. (c) 3 marks: 1 for the log law, 1 for the ×10 in the formula, 1 for the 10 dB conclusion.","marking_criteria":"(a) 1 mark. (b) 1 mark. (c) 3 marks: 1 for the log law, 1 for the ×10 in the formula, 1 for the 10 dB conclusion.","response_tools":["rich_text","math"],"response_requirement":"text","response_guidance":"Quote the logarithm law you use in (c); the mark is for the law, not the arithmetic."},"marking":"(a) 1 mark. (b) 1 mark. (c) 3 marks: 1 for the log law, 1 for the ×10 in the formula, 1 for the 10 dB conclusion.","h1":"A logarithmic scale turns multiplication into addition: a constant factor becomes a constant difference.","h2":"The ratio I/I₀ is 1000."},{"n":32,"t":"assess_parts","p":"A car loses 15% of its value each year. It cost $24 000 when new.\n\n(a) State the multiplier for one year of depreciation.\n(b) Calculate the value after 3 years, to the nearest dollar.\n(c) Calculate the number of complete years after which the value first falls below $8 000, testing successive years.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A car loses 15% of its value each year. It cost "},{"type":"text","text":"$24 000 when new."}]},{"type":"paragraph","content":[{"type":"text","text":"(a) State the multiplier for one year of depreciation.\n(b) Calculate the value after 3 years, to the nearest dollar.\n(c) Calculate the number of complete years after which the value first falls below "},{"type":"text","text":"$8 000, testing successive years."}]}]},"e":"Multiplier 0.85. Value after 3 years $14 739 and after 6 years $9 052. After 7 years 9 052 × 0.85 ≈ $7 694, the first value below $8 000.","m":9,"df":"hard","tp":"geometric sequences","st":"geometric sequences","cfg":{"source":"myp-mock-myp5-mock","question_number":32,"paper_section":"B","myp_criterion":"D","strand":"D(i)","next_time_hint":"For ''when does the value fall below X'', compute successive values and bracket the threshold.","assessment_style":"myp_mock","mock_exam_key":"myp5-mock","parts":[{"id":"a","label":"(a)","prompt":"State the depreciation multiplier for one year.","kind":"numeric","points":1,"hints":["A 15% loss leaves 85% of the value.","Write 85% as a decimal."],"strand":"D(i)","answer":0.85,"tolerance":0.001},{"id":"b","label":"(b)","prompt":"Calculate the value after 3 years, to the nearest dollar.","kind":"numeric","points":3,"hints":["Use 24000 × 0.85^3.","0.85³ = 0.614125."],"strand":"D(ii)","answer":14739,"tolerance":1,"unit":"$"},{"id":"c","label":"(c)","prompt":"Calculate the value after 6 years, to the nearest dollar.","kind":"numeric","points":3,"hints":["0.85^6 ≈ 0.37715.","24000 × 0.37715."],"strand":"D(iii)","answer":9052,"tolerance":3,"unit":"$"},{"id":"d","label":"(d)","prompt":"State the number of complete years before the value first falls below $8 000.","kind":"numeric","points":2,"hints":["Your 6-year value is still above 8000.","Multiply by 0.85 once more and compare."],"strand":"D(iv)","answer":7,"tolerance":0,"unit":"years"}],"marking":"(a) 1 mark. (b) 3 marks: 1 for the power, 1 for 0.614125, 1 for $14 739. (c) 3 marks: 1 for the sixth power, 1 for the product, 1 for $9 052. (d) 2 marks: 1 for the 7th year value, 1 for 7.","marking_criteria":"(a) 1 mark. (b) 3 marks: 1 for the power, 1 for 0.614125, 1 for $14 739. (c) 3 marks: 1 for the sixth power, 1 for the product, 1 for $9 052. (d) 2 marks: 1 for the 7th year value, 1 for 7.","response_tools":["rich_text","math","table"],"response_requirement":"text","response_guidance":"Tabulate the year-by-year values in the workspace; (d) needs the bracketing years, not a guess."},"marking":"(a) 1 mark. (b) 3 marks: 1 for the power, 1 for 0.614125, 1 for $14 739. (c) 3 marks: 1 for the sixth power, 1 for the product, 1 for $9 052. (d) 2 marks: 1 for the 7th year value, 1 for 7.","h1":"For ''when does the value fall below X'', compute successive values and bracket the threshold.","h2":"A 15% loss leaves 85% of the value."},{"n":33,"t":"assess_parts","p":"In a geometric sequence the first term is 8 and the common ratio is 1/2.\n\n(a) Write the first four terms.\n(b) Calculate the sum of the first 6 terms.\n(c) Calculate the sum to infinity.\n(d) Explain why the sum of the first 6 terms is already close to the sum to infinity.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"In a geometric sequence the first term is 8 and the common ratio is 1/2."}]},{"type":"paragraph","content":[{"type":"text","text":"(a) Write the first four terms.\n(b) Calculate the sum of the first 6 terms.\n(c) Calculate the sum to infinity.\n(d) Explain why the sum of the first 6 terms is already close to the sum to infinity."}]}]},"e":"Terms 8, 4, 2, 1, 0.5, 0.25 give S_6 = 15.75 and S∞ = 16; the missing tail is exactly 0.25, the seventh term onwards, which halves away rapidly.","m":9,"df":"hard","tp":"geometric sequences","st":"geometric sequences","cfg":{"source":"myp-mock-myp5-mock","question_number":33,"paper_section":"B","myp_criterion":"D","strand":"D(i)","next_time_hint":"For |r| < 1 the tail after n terms is r^n/(1 − r) times the first term: it shrinks geometrically.","assessment_style":"myp_mock","mock_exam_key":"myp5-mock","parts":[{"id":"a","label":"(a)","prompt":"State the 4th term.","kind":"numeric","points":1,"hints":["Multiply by 1/2 for each successive term.","8, 4, 2, then one more halving."],"strand":"D(i)","answer":1,"tolerance":0},{"id":"b","label":"(b)","prompt":"Calculate the sum of the first 6 terms.","kind":"numeric","points":3,"hints":["Use S_n = a(1 − r^n)/(1 − r).","8(1 − 1/64)/(0.5)."],"strand":"D(ii)","answer":15.75,"tolerance":0.02},{"id":"c","label":"(c)","prompt":"Calculate the sum to infinity.","kind":"numeric","points":2,"hints":["S∞ = a/(1 − r) because |r| < 1.","8 ÷ 0.5."],"strand":"D(iii)","answer":16,"tolerance":0},{"id":"d","label":"(d)","prompt":"Explain why six terms already give almost the whole sum.","kind":"text","points":3,"hints":["Compare your two sums.","What size is the remaining tail after six terms?"],"strand":"D(iv)","accepted":["the sixth term is only 0.25 and every later term is smaller still, so the tail beyond six terms adds just 0.25 to reach 16"],"keywords":[["sixth"],["term"],["later"],["smaller"],["tail"],["beyond"]],"minKeywordGroups":4}],"marking":"(a) 1 mark. (b) 3 marks: 1 for the formula, 1 for 63/64, 1 for 15.75. (c) 2 marks: 1 for the formula, 1 for 16. (d) 3 marks: 1 for the comparison, 1 for the 0.25 tail, 1 for the halving argument.","marking_criteria":"(a) 1 mark. (b) 3 marks: 1 for the formula, 1 for 63/64, 1 for 15.75. (c) 2 marks: 1 for the formula, 1 for 16. (d) 3 marks: 1 for the comparison, 1 for the 0.25 tail, 1 for the halving argument.","response_tools":["rich_text","math"],"response_requirement":"text","response_guidance":"Keep the fraction 63/64 in (b) until the last step; the exact form makes (d) easy."},"marking":"(a) 1 mark. (b) 3 marks: 1 for the formula, 1 for 63/64, 1 for 15.75. (c) 2 marks: 1 for the formula, 1 for 16. (d) 3 marks: 1 for the comparison, 1 for the 0.25 tail, 1 for the halving argument.","h1":"For |r| < 1 the tail after n terms is r^n/(1 − r) times the first term: it shrinks geometrically.","h2":"Multiply by 1/2 for each successive term."},{"n":34,"t":"assess_parts","p":"A ladder has rungs whose lengths form an arithmetic sequence. The bottom rung is 60 cm and each rung above it is 2 cm shorter. There are 14 rungs.\n\n(a) State the length of the top rung.\n(b) Calculate the total length of timber needed for all 14 rungs.\n(c) Explain why the average rung length is the mean of the top and bottom rungs.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A ladder has rungs whose lengths form an arithmetic sequence. The bottom rung is 60 cm and each rung above it is 2 cm shorter. There are 14 rungs."}]},{"type":"paragraph","content":[{"type":"text","text":"(a) State the length of the top rung.\n(b) Calculate the total length of timber needed for all 14 rungs.\n(c) Explain why the average rung length is the mean of the top and bottom rungs."}]}]},"e":"Top rung 34 cm gives S_14 = 7(94) = 658 cm and a mean of 47 cm. In an arithmetic sequence the symmetric pairs all have the same total, so the mean is the average of the end terms.","m":8,"df":"hard","tp":"arithmetic sequences","st":"arithmetic sequences","cfg":{"source":"myp-mock-myp5-mock","question_number":34,"paper_section":"B","myp_criterion":"C","strand":"C(i)","next_time_hint":"An arithmetic mean of the end terms works because of the symmetry of equal steps; say so explicitly.","assessment_style":"myp_mock","mock_exam_key":"myp5-mock","parts":[{"id":"a","label":"(a)","prompt":"State the length of the top rung, in centimetres.","kind":"numeric","points":1,"hints":["13 steps of 2 cm separate the 1st and 14th rungs.","60 − 2(13)."],"strand":"C(i)","answer":34,"tolerance":0,"unit":"cm"},{"id":"b","label":"(b)","prompt":"Calculate the total length of timber, in centimetres.","kind":"numeric","points":3,"hints":["The rung lengths form an arithmetic series: S_n = n/2 × (first + last).","There are 14 rungs, so evaluate 7 × 94."],"strand":"C(ii)","answer":658,"tolerance":0,"unit":"cm"},{"id":"c","label":"(c)","prompt":"State the mean rung length, in centimetres.","kind":"numeric","points":1,"hints":["The mean is the total divided by 14.","Or use (60 + 34)/2."],"strand":"C(iii)","answer":47,"tolerance":0,"unit":"cm"},{"id":"d","label":"(d)","prompt":"Explain why the mean equals the average of the end rungs.","kind":"text","points":3,"hints":["Write the terms and pair the first with the last.","Do the pairs have equal sums?"],"strand":"C(iv)","accepted":["in an arithmetic sequence the terms are evenly spaced, so first plus last equals second plus second-last and so on; every pair has the same sum, making the mean the average of the two end terms"],"keywords":[["arithmetic"],["sequence"],["terms"],["evenly"],["spaced"],["first"]],"minKeywordGroups":4}],"marking":"(a) 1 mark. (b) 3 marks: 1 for the formula, 1 for 94, 1 for 658. (c) 1 mark. (d) 3 marks: 1 for even spacing, 1 for the pairing, 1 for the conclusion.","marking_criteria":"(a) 1 mark. (b) 3 marks: 1 for the formula, 1 for 94, 1 for 658. (c) 1 mark. (d) 3 marks: 1 for even spacing, 1 for the pairing, 1 for the conclusion.","response_tools":["rich_text","math"],"response_requirement":"text","response_guidance":"The pairing argument in (d) is what earns the marks — not a numerical example."},"marking":"(a) 1 mark. (b) 3 marks: 1 for the formula, 1 for 94, 1 for 658. (c) 1 mark. (d) 3 marks: 1 for even spacing, 1 for the pairing, 1 for the conclusion.","h1":"An arithmetic mean of the end terms works because of the symmetry of equal steps; say so explicitly.","h2":"13 steps of 2 cm separate the 1st and 14th rungs."},{"n":35,"t":"assess_parts","p":"A town''s population P after t years is modelled as P = 12 000 × 1.03^t.\n\n(a) State the population growth rate per year.\n(b) Calculate the population after 10 years, to the nearest whole person.\n(c) Calculate the time for the population to double, to 2 decimal places.\n(d) State one limitation of this model.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A town''s population P after t years is modelled as P = 12 000 × 1.03^t."}]},{"type":"paragraph","content":[{"type":"text","text":"(a) State the population growth rate per year.\n(b) Calculate the population after 10 years, to the nearest whole person.\n(c) Calculate the time for the population to double, to 2 decimal places.\n(d) State one limitation of this model."}]}]},"e":"The multiplier 1.03 is a 3% annual increase. P(10) ≈ 16 127. Doubling: t = log 2 / log 1.03 ≈ 23.45 years. The model assumes unlimited growth at a constant rate, which no real town sustains.","m":9,"df":"hard","tp":"modelling","st":"modelling","cfg":{"source":"myp-mock-myp5-mock","question_number":35,"paper_section":"B","myp_criterion":"D","strand":"D(i)","next_time_hint":"For an exponential model, the base gives the rate and logarithms give the time to reach a target.","assessment_style":"myp_mock","mock_exam_key":"myp5-mock","parts":[{"id":"a","label":"(a)","prompt":"State the annual growth rate, as a percentage.","kind":"numeric","points":1,"hints":["Subtract 1 from the multiplier 1.03.","0.03 as a percentage."],"strand":"D(i)","answer":3,"tolerance":0,"unit":"%"},{"id":"b","label":"(b)","prompt":"Calculate the population after 10 years.","kind":"numeric","points":3,"hints":["Substitute t = 10.","1.03^10 ≈ 1.3439."],"strand":"D(ii)","answer":16127,"tolerance":2,"unit":"people"},{"id":"c","label":"(c)","prompt":"Calculate the doubling time, in years, to 2 decimal places.","kind":"numeric","points":3,"hints":["Solve 1.03^t = 2 using logarithms.","t = log 2 ÷ log 1.03."],"strand":"D(iii)","answer":23.45,"tolerance":0.05,"unit":"years"},{"id":"d","label":"(d)","prompt":"State and justify one limitation of the model.","kind":"text","points":2,"hints":["Does a real population grow at a constant rate forever?","What about migration, housing or resources?"],"strand":"D(iv)","accepted":["it assumes a constant 3% growth forever, but real populations are limited by housing, resources and migration, so the rate will not stay constant"],"keywords":[["assumes"],["constant"],["growth"],["forever"],["real"],["populations"]],"minKeywordGroups":4}],"marking":"(a) 1 mark. (b) 3 marks: 1 for substitution, 1 for 1.03^10, 1 for 16 127. (c) 3 marks: 1 for the log equation, 1 for the evaluated logs, 1 for 23.45. (d) 2 marks: 1 for a valid limitation, 1 for justification.","marking_criteria":"(a) 1 mark. (b) 3 marks: 1 for substitution, 1 for 1.03^10, 1 for 16 127. (c) 3 marks: 1 for the log equation, 1 for the evaluated logs, 1 for 23.45. (d) 2 marks: 1 for a valid limitation, 1 for justification.","response_tools":["graph","rich_text","math"],"response_requirement":"graph","response_guidance":"Plot the model in the workspace to check the doubling time visually before computing it."},"marking":"(a) 1 mark. (b) 3 marks: 1 for substitution, 1 for 1.03^10, 1 for 16 127. (c) 3 marks: 1 for the log equation, 1 for the evaluated logs, 1 for 23.45. (d) 2 marks: 1 for a valid limitation, 1 for justification.","h1":"For an exponential model, the base gives the rate and logarithms give the time to reach a target.","h2":"Subtract 1 from the multiplier 1.03."},{"n":36,"t":"assess_parts","p":"A rectangle has a perimeter of 40 cm. Its length is x cm.\n\n(a) Write the width in terms of x.\n(b) Show that the area is A = 20x − x².\n(c) State the value of x that maximises the area.\n(d) Calculate the maximum area.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A rectangle has a perimeter of 40 cm. Its length is x cm."}]},{"type":"paragraph","content":[{"type":"text","text":"(a) Write the width in terms of x.\n(b) Show that the area is A = 20x − x².\n(c) State the value of x that maximises the area.\n(d) Calculate the maximum area."}]}]},"e":"Width 20 − x gives A = 20x − x², and completing the square gives 100 − (x − 10)², so the maximum area is 100 cm² at x = 10: a square.","m":7,"df":"hard","tp":"quadratic functions","st":"quadratic functions","cfg":{"source":"myp-mock-myp5-mock","question_number":36,"paper_section":"B","myp_criterion":"D","strand":"D(i)","next_time_hint":"A downward parabola y = −(x − h)² + k peaks at x = h; completing the square locates it exactly.","assessment_style":"myp_mock","mock_exam_key":"myp5-mock","parts":[{"id":"a","label":"(a)","prompt":"State the width when the length is x, in centimetres.","kind":"expression","points":1,"hints":["The two lengths and two widths total 40.","So one length plus one width is 20."],"strand":"D(i)","accepted":["20 - x"]},{"id":"b","label":"(b)","prompt":"State the coefficient of x in the area expression 20x − x².","kind":"numeric","points":1,"hints":["The area is length × width.","Multiply out x(20 − x)."],"strand":"D(ii)","answer":20,"tolerance":0},{"id":"c","label":"(c)","prompt":"State the length that maximises the area, in centimetres.","kind":"numeric","points":2,"hints":["Complete the square: A = 100 − (x − 10)².","The squared term is smallest when it is zero."],"strand":"D(iii)","answer":10,"tolerance":0,"unit":"cm"},{"id":"d","label":"(d)","prompt":"Calculate the maximum area, in square centimetres.","kind":"numeric","points":2,"hints":["Substitute x = 10 into 20x − x².","200 − 100."],"strand":"D(iv)","answer":100,"tolerance":0,"unit":"cm²"},{"id":"e","label":"(e)","prompt":"Describe the shape of the rectangle with the maximum area.","kind":"text","points":1,"hints":["What are its length and width at the maximum?","A rectangle with equal sides has a special name."],"strand":"D(iv)","accepted":["a square with sides of 10 cm"]}],"marking":"(a) 1 mark. (b) 1 mark. (c) 2 marks: 1 for completing the square, 1 for x = 10. (d) 2 marks: 1 for substituting, 1 for 100. (e) 1 mark.","marking_criteria":"(a) 1 mark. (b) 1 mark. (c) 2 marks: 1 for completing the square, 1 for x = 10. (d) 2 marks: 1 for substituting, 1 for 100. (e) 1 mark.","response_tools":["rich_text","math","graph"],"response_requirement":"text","response_guidance":"Complete the square in (c); it proves the maximum rather than assuming the midpoint."},"marking":"(a) 1 mark. (b) 1 mark. (c) 2 marks: 1 for completing the square, 1 for x = 10. (d) 2 marks: 1 for substituting, 1 for 100. (e) 1 mark.","h1":"A downward parabola y = −(x − h)² + k peaks at x = h; completing the square locates it exactly.","h2":"The two lengths and two widths total 40."},{"n":37,"t":"assess_parts","p":"A loan of $6 000 charges 1.5% interest per month on the outstanding balance. No repayments are made for 8 months.\n\n(a) State the monthly multiplier.\n(b) Calculate the amount owed after 8 months, to the nearest cent.\n(c) Calculate the total interest charged. Explain why this exceeds 8 × 1.5% of $6 000.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A loan of "},{"type":"text","text":"$6 000 charges 1.5% interest per month on the outstanding balance. No repayments are made for 8 months."}]},{"type":"paragraph","content":[{"type":"text","text":"(a) State the monthly multiplier.\n(b) Calculate the amount owed after 8 months, to the nearest cent.\n(c) Calculate the total interest charged. Explain why this exceeds 8 × 1.5% of "},{"type":"text","text":"$6 000."}]}]},"e":"6000 × 1.015^8 = $6 758.94, so the interest is $758.94 against $720 for constant simple charges, because the balance compounds monthly.","m":8,"df":"hard","tp":"compound interest","st":"compound interest","cfg":{"source":"myp-mock-myp5-mock","question_number":37,"paper_section":"B","myp_criterion":"D","strand":"D(i)","next_time_hint":"Monthly compounding multiplies the balance repeatedly, so the total interest exceeds the sum of the simple monthly rates.","assessment_style":"myp_mock","mock_exam_key":"myp5-mock","parts":[{"id":"a","label":"(a)","prompt":"State the monthly multiplier.","kind":"numeric","points":1,"hints":["A 1.5% charge adds 1.5% of the balance.","Write 101.5% as a decimal."],"strand":"D(i)","answer":1.015,"tolerance":0.0005},{"id":"b","label":"(b)","prompt":"Calculate the amount owed after 8 months, to the nearest cent.","kind":"numeric","points":3,"hints":["Use 6000 × 1.015^8.","1.015^8 ≈ 1.12649."],"strand":"D(ii)","answer":6758.94,"tolerance":0.05,"unit":"$"},{"id":"c","label":"(c)","prompt":"Calculate the total interest charged.","kind":"numeric","points":1,"hints":["Interest paid is the amount owed minus the money borrowed.","Subtract $6 000 from your 8-month balance."],"strand":"D(iii)","answer":758.94,"tolerance":0.05,"unit":"$"},{"id":"d","label":"(d)","prompt":"Explain why the interest exceeds 8 × 1.5% of $6 000.","kind":"text","points":3,"hints":["What balance is each month''s 1.5% charged on?","Does the balance stay at $6 000?"],"strand":"D(iv)","accepted":["each month''s interest is charged on a balance that already includes earlier interest, so the interest itself earns interest and the total exceeds the $720 a constant charge would give"],"keywords":[["month''s"],["interest"],["charged"],["balance"],["already"],["includes"]],"minKeywordGroups":4}],"marking":"(a) 1 mark. (b) 3 marks: 1 for the power, 1 for 1.12649, 1 for $6 758.94. (c) 1 mark. (d) 3 marks: 1 for the growing balance, 1 for the $720 comparison, 1 for the consequence.","marking_criteria":"(a) 1 mark. (b) 3 marks: 1 for the power, 1 for 1.12649, 1 for $6 758.94. (c) 1 mark. (d) 3 marks: 1 for the growing balance, 1 for the $720 comparison, 1 for the consequence.","response_tools":["rich_text","math"],"response_requirement":"text","response_guidance":"Give the exact formula in (b) and compare with $720 explicitly in (d)."},"marking":"(a) 1 mark. (b) 3 marks: 1 for the power, 1 for 1.12649, 1 for $6 758.94. (c) 1 mark. (d) 3 marks: 1 for the growing balance, 1 for the $720 comparison, 1 for the consequence.","h1":"Monthly compounding multiplies the balance repeatedly, so the total interest exceeds the sum of the simple monthly rates.","h2":"A 1.5% charge adds 1.5% of the balance."},{"n":38,"t":"assess_parts","p":"A fractal design is built from squares. The first square has area 64 cm². Each new square has 1/4 of the area of the previous one, and the design contains infinitely many squares.\n\n(a) State the area of the second square.\n(b) Calculate the total area of the first 3 squares.\n(c) Calculate the total area of the infinite design.\n(d) Explain why infinitely many squares occupy a finite area.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A fractal design is built from squares. The first square has area 64 cm². Each new square has 1/4 of the area of the previous one, and the design contains infinitely many squares."}]},{"type":"paragraph","content":[{"type":"text","text":"(a) State the area of the second square.\n(b) Calculate the total area of the first 3 squares.\n(c) Calculate the total area of the infinite design.\n(d) Explain why infinitely many squares occupy a finite area."}]}]},"e":"Areas 64, 16, 4, … sum to 64/(1 − 0.25) = 85.33 cm². Because each increment is a quarter of the last, the total converges: an infinite number of squares with a finite combined area.","m":9,"df":"hard","tp":"limits of series","st":"limits of series","cfg":{"source":"myp-mock-myp5-mock","question_number":38,"paper_section":"B","myp_criterion":"C","strand":"C(i)","next_time_hint":"An infinite geometric series with |r| < 1 converges; the sum is a/(1 − r).","assessment_style":"myp_mock","mock_exam_key":"myp5-mock","parts":[{"id":"a","label":"(a)","prompt":"State the area of the second square, in square centimetres.","kind":"numeric","points":1,"hints":["Each square has a quarter of the area of the one before.","Divide 64 by 4."],"strand":"C(i)","answer":16,"tolerance":0,"unit":"cm²"},{"id":"b","label":"(b)","prompt":"Calculate the total area of the first three squares.","kind":"numeric","points":2,"hints":["The third square has area 4.","64 + 16 + 4."],"strand":"C(ii)","answer":84,"tolerance":0,"unit":"cm²"},{"id":"c","label":"(c)","prompt":"Calculate the total area of the infinite design, to 2 decimal places.","kind":"numeric","points":3,"hints":["Use S∞ = a/(1 − r) with a = 64 and r = 0.25.","64 ÷ 0.75."],"strand":"C(iii)","answer":85.33,"tolerance":0.02,"unit":"cm²"},{"id":"d","label":"(d)","prompt":"Explain why infinitely many squares can occupy a finite area.","kind":"text","points":3,"hints":["How much does each new square add compared with the last?","Does the running total keep growing without limit?"],"strand":"C(iv)","accepted":["each new square adds only a quarter of the previous one, so the increments shrink geometrically and the running total converges to 85.33 cm² rather than growing without bound"],"keywords":[["square"],["adds"],["quarter"],["previous"],["increments"],["shrink"]],"minKeywordGroups":4}],"marking":"(a) 1 mark. (b) 2 marks: 1 for the third term, 1 for 84. (c) 3 marks: 1 for the formula, 1 for 0.75, 1 for 85.33. (d) 3 marks: 1 for the shrinking increment, 1 for convergence, 1 for the finite limit.","marking_criteria":"(a) 1 mark. (b) 2 marks: 1 for the third term, 1 for 84. (c) 3 marks: 1 for the formula, 1 for 0.75, 1 for 85.33. (d) 3 marks: 1 for the shrinking increment, 1 for convergence, 1 for the finite limit.","response_tools":["rich_text","math"],"response_requirement":"text","response_guidance":"Quote your running totals in (d) — the convergence is shown by the numbers, not by the word ''infinite''."},"marking":"(a) 1 mark. (b) 2 marks: 1 for the third term, 1 for 84. (c) 3 marks: 1 for the formula, 1 for 0.75, 1 for 85.33. (d) 3 marks: 1 for the shrinking increment, 1 for convergence, 1 for the finite limit.","h1":"An infinite geometric series with |r| < 1 converges; the sum is a/(1 − r).","h2":"Each square has a quarter of the area of the one before."},{"n":39,"t":"assess_parts","p":"Simplify and evaluate each expression, showing the index law used.\n\n(a) 3^4 × 3^2 ÷ 3^3\n(b) (5^3)^2 ÷ 5^4\n(c) 2^−3 × 2^5","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Simplify and evaluate each expression, showing the index law used."}]},{"type":"paragraph","content":[{"type":"text","text":"(a) 3^4 × 3^2 ÷ 3^3\n(b) (5^3)^2 ÷ 5^4\n(c) 2^−3 × 2^5"}]}]},"e":"(a) 3^(4+2−3) = 3^3 = 27. (b) 5^(6−4) = 5^2 = 25. (c) 2^(−3+5) = 2^2 = 4. The laws are: add indices when multiplying, subtract when dividing, multiply when raising a power to a power.","m":7,"df":"hard","tp":"indices","st":"indices","cfg":{"source":"myp-mock-myp5-mock","question_number":39,"paper_section":"B","myp_criterion":"C","strand":"C(i)","next_time_hint":"Handle the indices first, then evaluate the single remaining power.","assessment_style":"myp_mock","mock_exam_key":"myp5-mock","parts":[{"id":"a","label":"(a)","prompt":"Evaluate 3^4 × 3^2 ÷ 3^3.","kind":"numeric","points":2,"hints":["Multiply by adding the indices, divide by subtracting.","4 + 2 − 3 = 3, so the answer is 3^3."],"strand":"C(i)","answer":27,"tolerance":0},{"id":"b","label":"(b)","prompt":"Evaluate (5^3)^2 ÷ 5^4.","kind":"numeric","points":2,"hints":["A power of a power multiplies the indices: (5^3)^2 = 5^6.","Then subtract the index 4."],"strand":"C(ii)","answer":25,"tolerance":0},{"id":"c","label":"(c)","prompt":"Evaluate 2^−3 × 2^5.","kind":"numeric","points":2,"hints":["Add the indices: −3 + 5 = 2.","Then evaluate 2^2."],"strand":"C(iii)","answer":4,"tolerance":0},{"id":"d","label":"(d)","prompt":"State the index law used to simplify 2^−3 × 2^5, in the form a^m × a^n = …","kind":"expression","points":1,"hints":["What happens to the indices when powers of the same base are multiplied?","State the law in the form a^m × a^n = …"],"strand":"C(iii)","accepted":["add the indices when multiplying powers of the same base"],"keywords":[["indices"],["multiplying"],["powers"],["base"]],"minKeywordGroups":3}],"marking":"(a) 2 marks: 1 for the combined index, 1 for 27. (b) 2 marks: 1 for 5^6, 1 for 25. (c) 2 marks: 1 for 2^2, 1 for 4. (d) 1 mark.","marking_criteria":"(a) 2 marks: 1 for the combined index, 1 for 27. (b) 2 marks: 1 for 5^6, 1 for 25. (c) 2 marks: 1 for 2^2, 1 for 4. (d) 1 mark.","response_tools":["rich_text","math"],"response_requirement":"text","response_guidance":"Write each law before applying it; the final values alone will not earn full marks."},"marking":"(a) 2 marks: 1 for the combined index, 1 for 27. (b) 2 marks: 1 for 5^6, 1 for 25. (c) 2 marks: 1 for 2^2, 1 for 4. (d) 1 mark.","h1":"Handle the indices first, then evaluate the single remaining power.","h2":"Multiply by adding the indices, divide by subtracting."},{"n":40,"t":"assess_parts","p":"A runner''s weekly distance increases by 10% each week. She runs 12 km in week 1.\n\n(a) Calculate the distance in week 4, to 2 decimal places.\n(b) Calculate the total distance run in the first 6 weeks.\n(c) Explain why this plan cannot continue indefinitely, using a calculation for week 30.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A runner''s weekly distance increases by 10% each week. She runs 12 km in week 1."}]},{"type":"paragraph","content":[{"type":"text","text":"(a) Calculate the distance in week 4, to 2 decimal places.\n(b) Calculate the total distance run in the first 6 weeks.\n(c) Explain why this plan cannot continue indefinitely, using a calculation for week 30."}]}]},"e":"Week 4 is 12 × 1.1³ = 15.97 km; the six-week total is 92.59 km. Week 30 would be 12 × 1.1^29 ≈ 190 km, which is not physically sustainable, so the model breaks down.","m":10,"df":"hard","tp":"modelling","st":"modelling","cfg":{"source":"myp-mock-myp5-mock","question_number":40,"paper_section":"B","myp_criterion":"D","strand":"D(i)","next_time_hint":"An exponential model may fit the early data yet fail eventually; always test it at a distant value.","assessment_style":"myp_mock","mock_exam_key":"myp5-mock","parts":[{"id":"a","label":"(a)","prompt":"Calculate the distance in week 4, to 2 decimal places.","kind":"numeric","points":2,"hints":["The multiplier is 1.1 and week 1 is the starting point.","12 × 1.1^3."],"strand":"D(i)","answer":15.97,"tolerance":0.02,"unit":"km"},{"id":"b","label":"(b)","prompt":"Calculate the total distance for the first 6 weeks, to 2 decimal places.","kind":"numeric","points":3,"hints":["Use S_n = a(r^n − 1)/(r − 1) with r = 1.1.","12(1.1^6 − 1)/0.1."],"strand":"D(ii)","answer":92.59,"tolerance":0.05,"unit":"km"},{"id":"c","label":"(c)","prompt":"Calculate the weekly distance predicted for week 30, to the nearest kilometre.","kind":"numeric","points":3,"hints":["Use 12 × 1.1^29.","1.1^29 ≈ 15.86."],"strand":"D(iii)","answer":190,"tolerance":2,"unit":"km"},{"id":"d","label":"(d)","prompt":"Explain why the plan cannot continue indefinitely.","kind":"text","points":2,"hints":["Compare 190 km per week with what a person can run.","Can growth at 10% per week be sustained?"],"strand":"D(iv)","accepted":["week 30 would demand about 190 km in a week, far beyond sustainable human training, so the exponential model must fail: real training plateaus"],"keywords":[["week"],["demand"],["beyond"],["sustainable"],["human"],["training"]],"minKeywordGroups":4}],"marking":"(a) 2 marks: 1 for 1.1^3, 1 for 15.97. (b) 3 marks: 1 for the sum formula, 1 for 0.771561, 1 for 92.59. (c) 3 marks: 1 for the power, 1 for 15.86, 1 for 190. (d) 2 marks: 1 for the impossible distance, 1 for the conclusion.","marking_criteria":"(a) 2 marks: 1 for 1.1^3, 1 for 15.97. (b) 3 marks: 1 for the sum formula, 1 for 0.771561, 1 for 92.59. (c) 3 marks: 1 for the power, 1 for 15.86, 1 for 190. (d) 2 marks: 1 for the impossible distance, 1 for the conclusion.","response_tools":["graph","rich_text","math"],"response_requirement":"graph","response_guidance":"Plot the weekly distances in the workspace; the shape is the argument for (d)."},"marking":"(a) 2 marks: 1 for 1.1^3, 1 for 15.97. (b) 3 marks: 1 for the sum formula, 1 for 0.771561, 1 for 92.59. (c) 3 marks: 1 for the power, 1 for 15.86, 1 for 190. (d) 2 marks: 1 for the impossible distance, 1 for the conclusion.","h1":"An exponential model may fit the early data yet fail eventually; always test it at a distant value.","h2":"The multiplier is 1.1 and week 1 is the starting point."},{"n":41,"t":"assess_parts","p":"An investment of $3 000 grows at 6% per year compound interest.\n\n(a) Write the value after n years as an expression.\n(b) Calculate the value after 12 years, to the nearest cent.\n(c) Using logarithms, calculate the number of years for the investment to reach $6 000, to 2 decimal places.\n(d) Explain why the doubling time is the same whatever the initial amount.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An investment of "},{"type":"text","text":"$3 000 grows at 6% per year compound interest."}]},{"type":"paragraph","content":[{"type":"text","text":"(a) Write the value after n years as an expression.\n(b) Calculate the value after 12 years, to the nearest cent.\n(c) Using logarithms, calculate the number of years for the investment to reach "},{"type":"text","text":"$6 000, to 2 decimal places.\n(d) Explain why the doubling time is the same whatever the initial amount."}]}]},"e":"3000(1.06)^12 = $6 036.59. Doubling solves 1.06^n = 2, giving n ≈ 11.90 years; the factor 2 is independent of the amount invested, so the doubling time depends only on the rate.","m":10,"df":"hard","tp":"exponential equations","st":"exponential equations","cfg":{"source":"myp-mock-myp5-mock","question_number":41,"paper_section":"B","myp_criterion":"D","strand":"D(i)","next_time_hint":"Growth factors are ratios, so doubling times depend on the rate alone — divide out the initial amount.","assessment_style":"myp_mock","mock_exam_key":"myp5-mock","parts":[{"id":"a","label":"(a)","prompt":"Calculate the value after 12 years, to the nearest cent.","kind":"numeric","points":3,"hints":["Use 3000 × 1.06^12.","1.06^12 ≈ 2.0122."],"strand":"D(i)","answer":6036.59,"tolerance":0.05,"unit":"$"},{"id":"b","label":"(b)","prompt":"State the value of 6000 ÷ 3000, the factor by which the money must grow.","kind":"numeric","points":1,"hints":["Divide the target by the starting amount.","This equals 1.06^n."],"strand":"D(ii)","answer":2,"tolerance":0},{"id":"c","label":"(c)","prompt":"Calculate the number of years to double, to 2 decimal places.","kind":"numeric","points":3,"hints":["Solve 1.06^n = 2 with logarithms.","n = log 2 ÷ log 1.06."],"strand":"D(iii)","answer":11.9,"tolerance":0.05,"unit":"years"},{"id":"d","label":"(d)","prompt":"Explain why the doubling time does not depend on the initial amount.","kind":"text","points":3,"hints":["Write the doubling equation with P as the starting amount.","Does P cancel?"],"strand":"D(iv)","accepted":["doubling requires P(1.06)^n = 2P, and dividing both sides by P leaves 1.06^n = 2, so the starting amount cancels and only the rate matters"],"keywords":[["doubling"],["requires"],["p106n"],["dividing"],["sides"],["leaves"]],"minKeywordGroups":4}],"marking":"(a) 3 marks: 1 for the power, 1 for 2.0122, 1 for $6 036.59. (b) 1 mark. (c) 3 marks: 1 for the log equation, 1 for the evaluated logs, 1 for 11.90. (d) 3 marks: 1 for the equation with P, 1 for the cancellation, 1 for the conclusion.","marking_criteria":"(a) 3 marks: 1 for the power, 1 for 2.0122, 1 for $6 036.59. (b) 1 mark. (c) 3 marks: 1 for the log equation, 1 for the evaluated logs, 1 for 11.90. (d) 3 marks: 1 for the equation with P, 1 for the cancellation, 1 for the conclusion.","response_tools":["rich_text","math"],"response_requirement":"text","response_guidance":"Write the doubling equation with a symbol P in (d); the cancellation is the whole argument."},"marking":"(a) 3 marks: 1 for the power, 1 for 2.0122, 1 for $6 036.59. (b) 1 mark. (c) 3 marks: 1 for the log equation, 1 for the evaluated logs, 1 for 11.90. (d) 3 marks: 1 for the equation with P, 1 for the cancellation, 1 for the conclusion.","h1":"Growth factors are ratios, so doubling times depend on the rate alone — divide out the initial amount.","h2":"Use 3000 × 1.06^12."},{"n":42,"t":"assess_parts","p":"A pile of logs has 1 log in the top row, 2 in the next, 3 in the next, and so on down to 20 rows.\n\n(a) Calculate the total number of logs.\n(b) Explain why the total is the 20th triangular number.\n(c) A second pile has 25 rows. Calculate how many more logs it contains than the first pile.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A pile of logs has 1 log in the top row, 2 in the next, 3 in the next, and so on down to 20 rows."}]},{"type":"paragraph","content":[{"type":"text","text":"(a) Calculate the total number of logs.\n(b) Explain why the total is the 20th triangular number.\n(c) A second pile has 25 rows. Calculate how many more logs it contains than the first pile."}]}]},"e":"1 + 2 + … + 20 = 210, the 20th triangular number. The 25-row pile holds 325 logs, so the difference is 115 — rows 21 to 25 alone contribute 21 + 22 + 23 + 24 + 25 = 115.","m":10,"df":"hard","tp":"arithmetic series","st":"arithmetic series","cfg":{"source":"myp-mock-myp5-mock","question_number":42,"paper_section":"B","myp_criterion":"D","strand":"D(i)","next_time_hint":"Triangular numbers sum consecutive integers: T_n = n(n + 1)/2, and differences of totals are sums of the extra rows.","assessment_style":"myp_mock","mock_exam_key":"myp5-mock","parts":[{"id":"a","label":"(a)","prompt":"Calculate the total number of logs in the 20-row pile.","kind":"numeric","points":3,"hints":["Use S_n = n(n + 1)/2.","20 × 21 ÷ 2."],"strand":"D(i)","answer":210,"tolerance":0,"unit":"logs"},{"id":"b","label":"(b)","prompt":"Explain why the total is a triangular number.","kind":"text","points":2,"hints":["What is the number of logs in row r?","What does ''triangular number'' describe?"],"strand":"D(ii)","accepted":["row r contains r logs, so the total is 1 + 2 + … + 20, which is exactly the definition of the 20th triangular number T_20 = n(n + 1)/2"],"keywords":[["contains"],["logs"],["total"],["exactly"],["definition"],["20th"]],"minKeywordGroups":4},{"id":"c","label":"(c)","prompt":"Calculate the total number of logs in a 25-row pile.","kind":"numeric","points":3,"hints":["Use n = 25 in n(n + 1)/2.","25 × 26 ÷ 2."],"strand":"D(iii)","answer":325,"tolerance":0,"unit":"logs"},{"id":"d","label":"(d)","prompt":"Calculate how many more logs the 25-row pile contains.","kind":"numeric","points":2,"hints":["Both piles start with 1 log in the top row, so compare the totals.","Subtract 210 from 325."],"strand":"D(iv)","answer":115,"tolerance":0,"unit":"logs"}],"marking":"(a) 3 marks: 1 for the formula, 1 for 20 × 21, 1 for 210. (b) 2 marks: 1 for ''row r has r logs'', 1 for the triangular-number link. (c) 3 marks: 1 for n = 25, 1 for 650/2, 1 for 325. (d) 2 marks: 1 for the subtraction, 1 for 115.","marking_criteria":"(a) 3 marks: 1 for the formula, 1 for 20 × 21, 1 for 210. (b) 2 marks: 1 for ''row r has r logs'', 1 for the triangular-number link. (c) 3 marks: 1 for n = 25, 1 for 650/2, 1 for 325. (d) 2 marks: 1 for the subtraction, 1 for 115.","response_tools":["rich_text","math","table"],"response_requirement":"text","response_guidance":"Show the triangular-number formula in (a); the structure is the point, not the addition."},"marking":"(a) 3 marks: 1 for the formula, 1 for 20 × 21, 1 for 210. (b) 2 marks: 1 for ''row r has r logs'', 1 for the triangular-number link. (c) 3 marks: 1 for n = 25, 1 for 650/2, 1 for 325. (d) 2 marks: 1 for the subtraction, 1 for 115.","h1":"Triangular numbers sum consecutive integers: T_n = n(n + 1)/2, and differences of totals are sums of the extra rows.","h2":"Use S_n = n(n + 1)/2."},{"n":43,"t":"assess_parts","p":"The profit P (in dollars) of a stall selling n items is modelled by P = −2n² + 80n − 350.\n\n(a) Calculate the profit when 10 items are sold.\n(b) Calculate the two break-even values of n by solving −2n² + 80n − 350 = 0.\n(c) State the number of items that maximises profit.\n(d) Calculate the maximum profit.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The profit P (in dollars) of a stall selling n items is modelled by P = −2n² + 80n − 350."}]},{"type":"paragraph","content":[{"type":"text","text":"(a) Calculate the profit when 10 items are sold.\n(b) Calculate the two break-even values of n by solving −2n² + 80n − 350 = 0.\n(c) State the number of items that maximises profit.\n(d) Calculate the maximum profit."}]}]},"e":"P(10) = $250. Solving n² − 40n + 175 = 0 gives n = 5 and n = 35; the profit is positive between them. The vertex at n = 20 gives the maximum profit of $450.","m":10,"df":"hard","tp":"quadratic functions","st":"quadratic functions","cfg":{"source":"myp-mock-myp5-mock","question_number":43,"paper_section":"B","myp_criterion":"D","strand":"D(i)","next_time_hint":"For a quadratic model, break-even points are the roots and the optimum is at the vertex, halfway between them.","assessment_style":"myp_mock","mock_exam_key":"myp5-mock","parts":[{"id":"a","label":"(a)","prompt":"Calculate the profit when 10 items are sold, in dollars.","kind":"numeric","points":2,"hints":["Substitute n = 10 carefully, keeping the minus sign on the squared term.","−200 + 800 − 350."],"strand":"D(i)","answer":250,"tolerance":0,"unit":"$"},{"id":"b","label":"(b)","prompt":"State the smaller break-even value of n.","kind":"numeric","points":2,"hints":["Divide the equation by −2 to simplify.","(n − 5)(n − 35) = 0."],"strand":"D(ii)","answer":5,"tolerance":0,"unit":"items"},{"id":"c","label":"(c)","prompt":"State the larger break-even value of n.","kind":"numeric","points":2,"hints":["You already have one root, n = 5; the other factor supplies the second.","Set n − 35 = 0."],"strand":"D(ii)","answer":35,"tolerance":0,"unit":"items"},{"id":"d","label":"(d)","prompt":"State the number of items that maximises profit.","kind":"numeric","points":2,"hints":["The vertex lies halfway between the two roots.","(5 + 35) ÷ 2."],"strand":"D(iii)","answer":20,"tolerance":0,"unit":"items"},{"id":"e","label":"(e)","prompt":"Calculate the maximum profit, in dollars.","kind":"numeric","points":2,"hints":["Substitute n = 20 into the profit model.","−800 + 1600 − 350."],"strand":"D(iv)","answer":450,"tolerance":0,"unit":"$"}],"marking":"(a) 2 marks: 1 for substitution, 1 for $250. (b) 2 marks: 1 for factorising, 1 for 5. (c) 2 marks. (d) 2 marks: 1 for the midpoint, 1 for 20. (e) 2 marks: 1 for substitution, 1 for $450.","marking_criteria":"(a) 2 marks: 1 for substitution, 1 for $250. (b) 2 marks: 1 for factorising, 1 for 5. (c) 2 marks. (d) 2 marks: 1 for the midpoint, 1 for 20. (e) 2 marks: 1 for substitution, 1 for $450.","response_tools":["graph","rich_text","math"],"response_requirement":"graph","response_guidance":"Plot the profit curve in the workspace: the roots and the vertex are visible on the graph and confirm your algebra."},"marking":"(a) 2 marks: 1 for substitution, 1 for $250. (b) 2 marks: 1 for factorising, 1 for 5. (c) 2 marks. (d) 2 marks: 1 for the midpoint, 1 for 20. (e) 2 marks: 1 for substitution, 1 for $450.","h1":"For a quadratic model, break-even points are the roots and the optimum is at the vertex, halfway between them.","h2":"Substitute n = 10 carefully, keeping the minus sign on the squared term."},{"n":44,"t":"assess_parts","p":"A geometric series has first term 18 and common ratio −1/3.\n\n(a) Write the first four terms.\n(b) Calculate the sum of the first 4 terms.\n(c) Explain why the series converges even though the ratio is negative.\n(d) Calculate the sum to infinity.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A geometric series has first term 18 and common ratio −1/3."}]},{"type":"paragraph","content":[{"type":"text","text":"(a) Write the first four terms.\n(b) Calculate the sum of the first 4 terms.\n(c) Explain why the series converges even though the ratio is negative.\n(d) Calculate the sum to infinity."}]}]},"e":"Terms 18, −6, 2, −2/3 give S_4 = 40/3 ≈ 13.333, already close to S∞ = 18/(4/3) = 13.5, because |r| = 1/3 < 1 despite the alternating signs.","m":10,"df":"hard","tp":"limits of series","st":"limits of series","cfg":{"source":"myp-mock-myp5-mock","question_number":44,"paper_section":"B","myp_criterion":"C","strand":"C(i)","next_time_hint":"Convergence depends on |r|, not the sign: a negative ratio alternates but still shrinks.","assessment_style":"myp_mock","mock_exam_key":"myp5-mock","parts":[{"id":"a","label":"(a)","prompt":"State the fourth term.","kind":"numeric","points":1,"hints":["Multiply by −1/3 each time: 18, −6, 2, …","2 × (−1/3)."],"strand":"C(i)","answer":-0.667,"tolerance":0.002},{"id":"b","label":"(b)","prompt":"Calculate the sum of the first 4 terms, to 3 decimal places.","kind":"numeric","points":3,"hints":["Keep the signs: the odd-powered terms are negative.","Add 18 − 6 + 2 − 2/3."],"strand":"C(ii)","answer":13.333,"tolerance":0.02},{"id":"c","label":"(c)","prompt":"Explain why the series converges despite the negative ratio.","kind":"text","points":3,"hints":["What is |−1/3|?","Does convergence depend on the sign of r?"],"strand":"C(iii)","accepted":["the series converges because the size of the ratio, 1/3, is less than 1; the negative sign only makes the terms alternate in sign"],"keywords":[["series"],["converges"],["size"],["ratio"],["negative"],["sign"]],"minKeywordGroups":4},{"id":"d","label":"(d)","prompt":"Calculate the sum to infinity.","kind":"numeric","points":3,"hints":["Use S∞ = a/(1 − r) with r = −1/3.","The denominator becomes 1 + 1/3 = 4/3."],"strand":"C(iv)","answer":13.5,"tolerance":0.02}],"marking":"(a) 1 mark. (b) 3 marks: 1 for listing the terms, 1 for the signed sum, 1 for 13.333. (c) 3 marks: 1 for |r|, 1 for the sign''s effect, 1 for the conclusion. (d) 3 marks: 1 for the formula, 1 for 4/3, 1 for 13.5.","marking_criteria":"(a) 1 mark. (b) 3 marks: 1 for listing the terms, 1 for the signed sum, 1 for 13.333. (c) 3 marks: 1 for |r|, 1 for the sign''s effect, 1 for the conclusion. (d) 3 marks: 1 for the formula, 1 for 4/3, 1 for 13.5.","response_tools":["rich_text","math"],"response_requirement":"text","response_guidance":"Keep the signs in (b); the alternating terms are what make the estimate in (c) sensible."},"marking":"(a) 1 mark. (b) 3 marks: 1 for listing the terms, 1 for the signed sum, 1 for 13.333. (c) 3 marks: 1 for |r|, 1 for the sign''s effect, 1 for the conclusion. (d) 3 marks: 1 for the formula, 1 for 4/3, 1 for 13.5.","h1":"Convergence depends on |r|, not the sign: a negative ratio alternates but still shrinks.","h2":"Multiply by −1/3 each time: 18, −6, 2, …"},{"n":45,"t":"assess_parts","p":"A phone battery loses charge according to B = 100 × 0.92^t, where B is the percentage remaining after t hours of standby.\n\n(a) State the percentage lost each hour.\n(b) Calculate the percentage remaining after 6 hours, to 1 decimal place.\n(c) Using logarithms, calculate the time for the battery to fall to 50%, to 2 decimal places.\n(d) A user claims ''the battery loses 8% of 100 each hour, so it runs out after 12.5 hours''. Evaluate this claim.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A phone battery loses charge according to B = 100 × 0.92^t, where B is the percentage remaining after t hours of standby."}]},{"type":"paragraph","content":[{"type":"text","text":"(a) State the percentage lost each hour.\n(b) Calculate the percentage remaining after 6 hours, to 1 decimal place.\n(c) Using logarithms, calculate the time for the battery to fall to 50%, to 2 decimal places.\n(d) A user claims ''the battery loses 8% of 100 each hour, so it runs out after 12.5 hours''. Evaluate this claim."}]}]},"e":"0.92 keeps 92%, so 8% of the current charge is lost each hour. B(6) ≈ 60.6% and the 50% level is reached at t = log 0.5 / log 0.92 ≈ 8.31 hours. The 12.5-hour claim wrongly assumes a constant 8 percentage-point loss.","m":10,"df":"hard","tp":"modelling","st":"modelling","cfg":{"source":"myp-mock-myp5-mock","question_number":45,"paper_section":"B","myp_criterion":"D","strand":"D(i)","next_time_hint":"An exponential decay loses a constant PERCENTAGE of the current amount, not a constant amount: linear reasoning overestimates the lifetime.","assessment_style":"myp_mock","mock_exam_key":"myp5-mock","parts":[{"id":"a","label":"(a)","prompt":"State the percentage of charge lost each hour.","kind":"numeric","points":1,"hints":["The multiplier 0.92 keeps 92%.","100 − 92."],"strand":"D(i)","answer":8,"tolerance":0,"unit":"%"},{"id":"b","label":"(b)","prompt":"Calculate the percentage remaining after 6 hours, to 1 decimal place.","kind":"numeric","points":3,"hints":["Use 100 × 0.92^6.","0.92^6 ≈ 0.60636."],"strand":"D(ii)","answer":60.6,"tolerance":0.1,"unit":"%"},{"id":"c","label":"(c)","prompt":"Calculate the time to reach 50%, to 2 decimal places.","kind":"numeric","points":3,"hints":["Solve 0.92^t = 0.5 with logarithms.","t = log 0.5 ÷ log 0.92."],"strand":"D(iii)","answer":8.31,"tolerance":0.05,"unit":"hours"},{"id":"d","label":"(d)","prompt":"Evaluate the claim that the battery runs out after 12.5 hours.","kind":"text","points":3,"hints":["Is 8% of the current charge a constant 8 percentage points?","Compare 12.5 hours with your answer to (c)."],"strand":"D(iv)","accepted":["the claim is wrong: it treats the 8% as a constant 8 percentage points, but the model takes 8% of the current charge, so the battery reaches 50% after about 8.31 hours, not 12.5"],"keywords":[["claim"],["wrong"],["treats"],["constant"],["percentage"],["points"]],"minKeywordGroups":4}],"marking":"(a) 1 mark. (b) 3 marks: 1 for the power, 1 for 0.60636, 1 for 60.6%. (c) 3 marks: 1 for the log equation, 1 for the evaluated logs, 1 for 8.31. (d) 3 marks: 1 for identifying the linear error, 1 for the 8.31-hour comparison, 1 for a clear conclusion.","marking_criteria":"(a) 1 mark. (b) 3 marks: 1 for the power, 1 for 0.60636, 1 for 60.6%. (c) 3 marks: 1 for the log equation, 1 for the evaluated logs, 1 for 8.31. (d) 3 marks: 1 for identifying the linear error, 1 for the 8.31-hour comparison, 1 for a clear conclusion.","response_tools":["graph","rich_text","math"],"response_requirement":"graph","response_guidance":"Plot B against t in the workspace and mark the 50% level: the curve, not a straight line, is the counter-argument in (d)."},"marking":"(a) 1 mark. (b) 3 marks: 1 for the power, 1 for 0.60636, 1 for 60.6%. (c) 3 marks: 1 for the log equation, 1 for the evaluated logs, 1 for 8.31. (d) 3 marks: 1 for identifying the linear error, 1 for the 8.31-hour comparison, 1 for a clear conclusion.","h1":"An exponential decay loses a constant PERCENTAGE of the current amount, not a constant amount: linear reasoning overestimates the lifetime.","h2":"The multiplier 0.92 keeps 92%."}]'::jsonb) as x;

create temporary table _myp_mock_forward_options (
  option_id uuid primary key,
  question_id uuid not null,
  position integer not null,
  label text not null,
  is_correct boolean not null,
  unique (question_id, position)
) on commit drop;

insert into _myp_mock_forward_options (option_id, question_id, position, label, is_correct)
select ('d5000000-0000-4000-8000' || lpad((300000 + s.question_number * 100 + v.position::integer)::text, 12, '0'))::uuid,
       s.question_id, v.position::integer, v.label,
       (s.config->'option_key') @> to_jsonb(v.position::integer)
  from _myp_mock_forward_stage s
 cross join lateral jsonb_array_elements_text(coalesce(s.config->'option_labels', '[]'::jsonb)) with ordinality as v(label, position);

insert into _myp_mock_forward_options (option_id, question_id, position, label, is_correct)
select ('d5000000-0000-4000-8000' || lpad((310000 + s.question_number * 100 + v.position::integer)::text, 12, '0'))::uuid,
       s.question_id, v.position::integer, v.label, true
  from _myp_mock_forward_stage s
 cross join lateral jsonb_array_elements_text(coalesce(s.config->'accepted', '[]'::jsonb)) with ordinality as v(label, position);

create temporary table _myp_mock_forward_hints (
  hint_id uuid primary key,
  question_id uuid not null,
  level smallint not null,
  body text not null,
  unique (question_id, level)
) on commit drop;

insert into _myp_mock_forward_hints (hint_id, question_id, level, body)
select ('d5000000-0000-4000-8000' || lpad((500000 + s.question_number * 10 + v.level)::text, 12, '0'))::uuid,
       s.question_id, v.level::smallint, v.body
  from _myp_mock_forward_stage s
 cross join lateral (values (1, s.hint_one), (2, s.hint_two)) as v(level, body)
 where v.body is not null and char_length(btrim(v.body)) between 8 and 800;

do $$
declare
  v_questions integer;
  v_paper_rows integer;
  v_attempts integer;
  v_extra_options integer;
  v_duplicate_positions integer;
  v_id_collisions integer;
  v_other_paper_links integer;
begin
  -- A row lock prevents a new attempt from being created between this check and
  -- the content update below. If a paper has ever been attempted, stop rather
  -- than reinterpret a candidate's saved response against new question text.
  perform 1 from public.exams
   where id = 'd5000000-0000-4000-8000-000000000002'::uuid and organization_id = '0a400000-0000-4000-8000-000000000001'::uuid
   for update;
  if not found then
    raise exception 'MYP5-MOCK-2026: fixed examination row is missing or belongs to another tenant';
  end if;
  perform 1 from public.quizzes
   where id = 'd5000000-0000-4000-8000-000000000001'::uuid and organization_id = '0a400000-0000-4000-8000-000000000001'::uuid
   for update;
  if not found then
    raise exception 'MYP5-MOCK-2026: fixed quiz row is missing or belongs to another tenant';
  end if;
  if not exists (
    select 1 from public.exams
     where id = 'd5000000-0000-4000-8000-000000000002'::uuid
       and organization_id = '0a400000-0000-4000-8000-000000000001'::uuid
       and quiz_id = 'd5000000-0000-4000-8000-000000000001'::uuid
  ) then
    raise exception 'MYP5-MOCK-2026: the fixed examination is no longer linked to its fixed quiz row';
  end if;

  select count(*) into v_attempts from public.exam_attempts where exam_id = 'd5000000-0000-4000-8000-000000000002'::uuid;
  if v_attempts <> 0 then
    raise exception 'MYP5-MOCK-2026: refusing to rewrite a paper with % attempt(s); preserve active and historical sessions, then retry with an approved snapshot plan', v_attempts;
  end if;

  select count(*) into v_questions
    from _myp_mock_forward_stage s
    join public.questions q on q.id = s.question_id and q.organization_id = '0a400000-0000-4000-8000-000000000001'::uuid;
  if v_questions <> 45 then
    raise exception 'MYP5-MOCK-2026: found % of the expected 45 fixed question rows', v_questions;
  end if;

  select count(*) into v_paper_rows
    from _myp_mock_forward_stage s
    join public.quiz_questions qq on qq.question_id = s.question_id and qq.quiz_id = 'd5000000-0000-4000-8000-000000000001'::uuid;
  if v_paper_rows <> 45 then
    raise exception 'MYP5-MOCK-2026: found % of the expected 45 fixed quiz-question rows', v_paper_rows;
  end if;
  select count(*) into v_other_paper_links
    from public.quiz_questions qq
    join _myp_mock_forward_stage s on s.question_id = qq.question_id
   where qq.quiz_id <> 'd5000000-0000-4000-8000-000000000001'::uuid;
  if v_other_paper_links <> 0 then
    raise exception 'MYP5-MOCK-2026: % target question link(s) belong to another quiz; refusing to rewrite shared content', v_other_paper_links;
  end if;

  -- Existing options must be representable by the authored positions. We may
  -- update those rows in place or add a missing row, but never delete or remap
  -- an unexpected option because an historical answer may reference its UUID.
  select count(*) into v_extra_options
    from public.question_options o
    join _myp_mock_forward_stage s on s.question_id = o.question_id
   where not exists (
     select 1 from _myp_mock_forward_options d
      where d.question_id = o.question_id and d.position = o.position
   );
  if v_extra_options <> 0 then
    raise exception 'MYP5-MOCK-2026: % unexpected option row(s) would require destructive cleanup', v_extra_options;
  end if;

  select count(*) into v_duplicate_positions
    from (
      select o.question_id, o.position
        from public.question_options o
        join _myp_mock_forward_stage s on s.question_id = o.question_id
       group by o.question_id, o.position
      having count(*) > 1
    ) duplicates;
  if v_duplicate_positions <> 0 then
    raise exception 'MYP5-MOCK-2026: duplicate option positions require manual reconciliation';
  end if;

  select count(*) into v_id_collisions
    from _myp_mock_forward_options d
    join public.question_options o on o.id = d.option_id
   where o.question_id <> d.question_id or o.position <> d.position;
  if v_id_collisions <> 0 then
    raise exception 'MYP5-MOCK-2026: deterministic option IDs collide with unrelated rows';
  end if;
end $$;

update public.questions q
   set type = s.question_type,
       prompt = s.prompt,
       prompt_doc = s.prompt_doc,
       explanation = s.explanation,
       explanation_doc = null,
       points = s.points,
       difficulty = s.difficulty,
       topic = s.topic,
       subtopic = s.subtopic,
       tags = array['MYP 5', 'Mathematics', 'mock', 'mock-examination', 'MYP5-MOCK-2026'],
       config = s.config,
       curriculum = 'MYP',
       curriculum_course = 'MYP 5 Mathematics',
       subject_id = '0a400000-0000-4000-8000-000000000030'::uuid
  from _myp_mock_forward_stage s
 where q.id = s.question_id
   and q.organization_id = '0a400000-0000-4000-8000-000000000001'::uuid
   and (
     q.type is distinct from s.question_type
     or q.prompt is distinct from s.prompt
     or q.prompt_doc is distinct from s.prompt_doc
     or q.explanation is distinct from s.explanation
     or q.explanation_doc is not null
     or q.points is distinct from s.points
     or q.difficulty is distinct from s.difficulty
     or q.topic is distinct from s.topic
     or q.subtopic is distinct from s.subtopic
     or q.tags is distinct from array['MYP 5', 'Mathematics', 'mock', 'mock-examination', 'MYP5-MOCK-2026']
     or q.config is distinct from s.config
     or q.curriculum is distinct from 'MYP'
     or q.curriculum_course is distinct from 'MYP 5 Mathematics'
     or q.subject_id is distinct from '0a400000-0000-4000-8000-000000000030'::uuid
   );

update public.question_options o
   set label = d.label,
       is_correct = d.is_correct,
       content_doc = null
  from _myp_mock_forward_options d
 where o.question_id = d.question_id
   and o.position = d.position
   and (o.label is distinct from d.label or o.is_correct is distinct from d.is_correct or o.content_doc is not null);

insert into public.question_options (id, question_id, label, is_correct, position, content_doc)
select d.option_id, d.question_id, d.label, d.is_correct, d.position, null
  from _myp_mock_forward_options d
  left join public.question_options o on o.question_id = d.question_id and o.position = d.position
 where o.id is null
on conflict (id) do nothing;

update public.quiz_questions qq
   set position = s.question_number,
       points = s.points
  from _myp_mock_forward_stage s
 where qq.quiz_id = 'd5000000-0000-4000-8000-000000000001'::uuid
   and qq.question_id = s.question_id
   and (qq.position is distinct from s.question_number or qq.points is distinct from s.points);

update public.question_hints h
   set body = d.body,
       body_doc = null,
       status = 'published',
       source = 'manual',
       approved_by = coalesce(h.approved_by, '3c3ed712-f409-4aa1-a645-816418e22ec4'::uuid),
       approved_at = coalesce(h.approved_at, now()),
       published_at = coalesce(h.published_at, now())
  from _myp_mock_forward_hints d
 where h.exam_id = 'd5000000-0000-4000-8000-000000000002'::uuid
   and h.question_id = d.question_id
   and h.level = d.level
   and (
     h.body is distinct from d.body
     or h.body_doc is not null
     or h.status is distinct from 'published'
     or h.source is distinct from 'manual'
     or h.approved_by is null
     or h.approved_at is null
     or h.published_at is null
   );

insert into public.question_hints
  (id, organization_id, exam_id, question_id, level, body, body_doc, status, source,
   created_by, approved_by, approved_at, published_at)
select d.hint_id, '0a400000-0000-4000-8000-000000000001'::uuid, 'd5000000-0000-4000-8000-000000000002'::uuid, d.question_id, d.level, d.body, null,
       'published', 'manual', '3c3ed712-f409-4aa1-a645-816418e22ec4'::uuid, '3c3ed712-f409-4aa1-a645-816418e22ec4'::uuid, now(), now()
  from _myp_mock_forward_hints d
  left join public.question_hints h
    on h.exam_id = 'd5000000-0000-4000-8000-000000000002'::uuid and h.question_id = d.question_id and h.level = d.level
 where h.id is null
on conflict do nothing;

