update public.exams e
   set title = 'MYP5 Mathematics — Mock Examination',
       description = 'Grade 10 · MYP 5 · Mathematics · Mock Examination. Arithmetic and geometric sequences, recurrence relations, sigma notation, sums and limits, compound interest and depreciation, exponential and logarithmic models, quadratic functions and modelling. 45 questions, 259 marks: Section A (objective) and Section B (structured investigations).',
       instructions = 'MYP5 MATHEMATICS — MOCK EXAMINATION (Grade 10)

Time allowed: 2 hours 30 minutes.

SECTION A — Objective questions (questions 1–22).
Each question has one correct answer. Several items ask you to judge a claim rather than compute: read the whole statement before choosing.

SECTION B — Structured questions (questions 23–45).
Show your working. Marks are printed beside every part. Where a question asks you to CONSTRUCT a table or a graph, build it in the workspace: the representation itself is being assessed, and the typed answer records the value you read from it.

EXAMINATION OBJECTIVES. By the end of this paper you should be able to: recognise, generate and classify arithmetic and geometric sequences; use recurrence relations and sigma notation; derive and apply the nth term and sum formulas; determine whether an infinite geometric series converges and find its sum; solve problems involving compound interest, depreciation and loans; solve exponential equations using logarithms; analyse quadratic functions from their completed-square, factorised and graphical forms; and build and criticise mathematical models of real situations.

GENERAL INSTRUCTIONS.
1. A calculator is permitted throughout. Write the formula or the method you use, not just the answer.
2. Money is given to the nearest cent and other quantities to 3 significant figures unless a part states otherwise.
3. A hint is available on every part. Hints guide the method and never give the answer; using one costs no marks and is recorded only to support your revision.
4. Your answers save automatically; after a disconnection, reopen the paper and your work is restored.
5. Notation: u_n is the nth term, d the common difference, r the common ratio, and S_n the sum of the first n terms.

MARKS. Every part shows its marks. Section A is worth 60 marks and Section B 199 marks, out of a total of 259. Pass mark: your institution''s configured threshold (default 50%).',
       duration_minutes = 150,
       settings = coalesce(e.settings, '{}'::jsonb) || '{"randomize_questions":false,"randomize_options":false,"assessment_kind":"mock","grade_level":"10","curriculum":"MYP 5","subject":"Mathematics","total_marks":259,"source":"myp-mock-myp5-mock","mock_exam_key":"myp5-mock","mock_code":"MYP5-MOCK-2026","show_sections":true,"feedback":{"marking_criteria":true,"next_time_hint":true,"objective_structured_split":true,"topic_breakdown":true,"criterion_level_band":true}}'::jsonb
 where e.id = 'd5000000-0000-4000-8000-000000000002'::uuid
   and e.organization_id = '0a400000-0000-4000-8000-000000000001'::uuid
   and (
     e.title is distinct from 'MYP5 Mathematics — Mock Examination'
     or e.description is distinct from 'Grade 10 · MYP 5 · Mathematics · Mock Examination. Arithmetic and geometric sequences, recurrence relations, sigma notation, sums and limits, compound interest and depreciation, exponential and logarithmic models, quadratic functions and modelling. 45 questions, 259 marks: Section A (objective) and Section B (structured investigations).'
     or e.instructions is distinct from 'MYP5 MATHEMATICS — MOCK EXAMINATION (Grade 10)

Time allowed: 2 hours 30 minutes.

SECTION A — Objective questions (questions 1–22).
Each question has one correct answer. Several items ask you to judge a claim rather than compute: read the whole statement before choosing.

SECTION B — Structured questions (questions 23–45).
Show your working. Marks are printed beside every part. Where a question asks you to CONSTRUCT a table or a graph, build it in the workspace: the representation itself is being assessed, and the typed answer records the value you read from it.

EXAMINATION OBJECTIVES. By the end of this paper you should be able to: recognise, generate and classify arithmetic and geometric sequences; use recurrence relations and sigma notation; derive and apply the nth term and sum formulas; determine whether an infinite geometric series converges and find its sum; solve problems involving compound interest, depreciation and loans; solve exponential equations using logarithms; analyse quadratic functions from their completed-square, factorised and graphical forms; and build and criticise mathematical models of real situations.

GENERAL INSTRUCTIONS.
1. A calculator is permitted throughout. Write the formula or the method you use, not just the answer.
2. Money is given to the nearest cent and other quantities to 3 significant figures unless a part states otherwise.
3. A hint is available on every part. Hints guide the method and never give the answer; using one costs no marks and is recorded only to support your revision.
4. Your answers save automatically; after a disconnection, reopen the paper and your work is restored.
5. Notation: u_n is the nth term, d the common difference, r the common ratio, and S_n the sum of the first n terms.

MARKS. Every part shows its marks. Section A is worth 60 marks and Section B 199 marks, out of a total of 259. Pass mark: your institution''s configured threshold (default 50%).'
     or e.duration_minutes is distinct from 150
     or e.settings is distinct from (coalesce(e.settings, '{}'::jsonb) || '{"randomize_questions":false,"randomize_options":false,"assessment_kind":"mock","grade_level":"10","curriculum":"MYP 5","subject":"Mathematics","total_marks":259,"source":"myp-mock-myp5-mock","mock_exam_key":"myp5-mock","mock_code":"MYP5-MOCK-2026","show_sections":true,"feedback":{"marking_criteria":true,"next_time_hint":true,"objective_structured_split":true,"topic_breakdown":true,"criterion_level_band":true}}'::jsonb)
   );

do $$
declare
  v_questions integer;
  v_options integer;
  v_paper_rows integer;
  v_hints integer;
begin
  select count(*) into v_questions
    from _myp_mock_forward_stage s
    join public.questions q on q.id = s.question_id
   where q.organization_id = '0a400000-0000-4000-8000-000000000001'::uuid
     and q.type = s.question_type
     and q.prompt = s.prompt
     and q.prompt_doc = s.prompt_doc
     and q.explanation = s.explanation
     and q.explanation_doc is null
     and q.points = s.points
     and q.difficulty = s.difficulty
     and q.topic = s.topic
     and q.subtopic = s.subtopic
     and q.config = s.config;
  if v_questions <> 45 then
    raise exception 'MYP5-MOCK-2026: only % question rows match the authored forward payload after update', v_questions;
  end if;

  select count(*) into v_options
    from _myp_mock_forward_options d
    join public.question_options o
      on o.question_id = d.question_id and o.position = d.position
   where o.label = d.label and o.is_correct = d.is_correct and o.content_doc is null;
  if v_options <> (select count(*) from _myp_mock_forward_options) then
    raise exception 'MYP5-MOCK-2026: option rows did not reconcile to the authored payload';
  end if;

  select count(*) into v_paper_rows
    from _myp_mock_forward_stage s
    join public.quiz_questions qq
      on qq.quiz_id = 'd5000000-0000-4000-8000-000000000001'::uuid and qq.question_id = s.question_id
   where qq.position = s.question_number and qq.points = s.points;
  if v_paper_rows <> 45 then
    raise exception 'MYP5-MOCK-2026: only % quiz-question rows match the authored order and marks', v_paper_rows;
  end if;

  select count(*) into v_hints
    from _myp_mock_forward_hints d
    join public.question_hints h
      on h.exam_id = 'd5000000-0000-4000-8000-000000000002'::uuid and h.question_id = d.question_id and h.level = d.level
   where h.body = d.body and h.status = 'published';
  if v_hints <> (select count(*) from _myp_mock_forward_hints) then
    raise exception 'MYP5-MOCK-2026: only % authored hint rows were reconciled', v_hints;
  end if;

  if not exists (
    select 1 from public.quizzes q
     where q.id = 'd5000000-0000-4000-8000-000000000001'::uuid and q.organization_id = '0a400000-0000-4000-8000-000000000001'::uuid
       and q.settings @> '{"randomize_questions":false,"randomize_options":false,"assessment_kind":"mock","grade_level":"10","curriculum":"MYP 5","subject":"Mathematics","total_marks":259,"source":"myp-mock-myp5-mock","mock_exam_key":"myp5-mock","mock_code":"MYP5-MOCK-2026","duration_minutes":150,"sections":[{"id":"A","title":"Section A — Objective","questions":22,"marks":60,"instructions":"One correct answer per question. The options are written so a wrong choice identifies a specific misconception."},{"id":"B","title":"Section B — Structured","questions":23,"marks":199,"instructions":"Show your working. Every part carries its own marks, its own answer box and its own two hints."}]}'::jsonb
  ) then
    raise exception 'MYP5-MOCK-2026: quiz metadata did not reconcile';
  end if;
  if not exists (
    select 1 from public.exams e
     where e.id = 'd5000000-0000-4000-8000-000000000002'::uuid and e.organization_id = '0a400000-0000-4000-8000-000000000001'::uuid
       and e.duration_minutes = 150
       and e.settings @> '{"randomize_questions":false,"randomize_options":false,"assessment_kind":"mock","grade_level":"10","curriculum":"MYP 5","subject":"Mathematics","total_marks":259,"source":"myp-mock-myp5-mock","mock_exam_key":"myp5-mock","mock_code":"MYP5-MOCK-2026","show_sections":true,"feedback":{"marking_criteria":true,"next_time_hint":true,"objective_structured_split":true,"topic_breakdown":true,"criterion_level_band":true}}'::jsonb
  ) then
    raise exception 'MYP5-MOCK-2026: examination metadata did not reconcile';
  end if;
end $$;

commit;
